window.FAQ=(window.FAQ||[]).concat([
 {id:'hpx-001',thema:'hypotheek-producten',vraag:'Hoe verloopt de verhouding tussen rente en aflossing binnen een annuïteit?',antwoord:`Bij een annuïteit blijft de bruto maandlast gelijk zolang de rente niet wijzigt. In het begin bestaat de termijn vooral uit rente en weinig aflossing. Naarmate de schuld daalt, verschuift de verhouding naar meer aflossing. Daardoor daalt het renteaftrekvoordeel en stijgt de netto maandlast geleidelijk.`,tags:['annuïtair','netto maandlast','renteaftrek'],bron:'Wet IB 2001'},
 {id:'hpx-002',thema:'hypotheek-producten',vraag:'Waarom stijgt de netto maandlast van een annuïteitenhypotheek terwijl de bruto last gelijk blijft?',antwoord:`Het rentedeel van de termijn daalt elk jaar. Daarmee daalt ook het bedrag dat in aftrek komt. De bruto termijn blijft gelijk, dus het netto bedrag stijgt. Bespreek dit verloop met de klant en neem een netto maandlastenoverzicht over de looptijd op in het adviesrapport.`,tags:['annuïtair','netto maandlast','adviesrapport'],bron:''},
 {id:'hpx-003',thema:'hypotheek-producten',vraag:'Hoe leg je het verschil in totale rentelasten tussen annuïtair en lineair uit?',antwoord:`Bij lineair aflossen daalt de schuld vanaf de eerste maand sneller. Daardoor betaalt de klant over de hele looptijd minder rente dan bij annuïtair. Daar staat een hogere bruto maandlast in de beginjaren tegenover. Toon beide varianten naast elkaar met dezelfde rente en looptijd, zodat het verschil zuiver zichtbaar is.`,tags:['lineair','annuïtair','vergelijking'],bron:''},
 {id:'hpx-004',thema:'hypotheek-producten',vraag:'Wanneer past lineair aflossen beter bij een klant dan annuïtair?',antwoord:`Lineair past vooral bij klanten met ruimte in het budget in de beginjaren. Denk aan klanten die een inkomensdaling verwachten of op latere leeftijd schuldenvrij willen zijn. Ook bij een wens om het renterisico snel te verkleinen kan lineair passen. Leg vast waarom de hogere startlast verantwoord is.`,tags:['lineair','klantprofiel','vastlegging'],bron:''},
 {id:'hpx-005',thema:'hypotheek-producten',vraag:'Kan een klant binnen een lopende lening overstappen van lineair naar annuïtair?',antwoord:`Dat kan bij veel geldverstrekkers, maar vaak alleen op een rentewijzigingsdatum of tegen administratiekosten. Fiscaal is de overstap meestal geen probleem, zolang de schuld binnen de resterende looptijd volledig wordt afgelost. Let erop dat de resterende looptijd niet wordt verlengd. Controleer de voorwaarden van de geldverstrekker.`,tags:['lineair','annuïtair','omzetten','aflossingseis'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-006',thema:'hypotheek-producten',vraag:'Wat gebeurt er fiscaal als een klant een annuïtair leningdeel aflossingsvrij maakt?',antwoord:`Voor een eigenwoningschuld van na 2012 vervalt dan de renteaftrek over dat deel. Het deel voldoet niet meer aan de aflossingseis en gaat in de regel over naar box 3. Dit is niet terug te draaien door later weer annuïtair af te lossen. Waarschuw de klant vooraf en leg de keuze schriftelijk vast.`,tags:['aflossingsvrij','box 3','aflossingseis'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-007',thema:'hypotheek-producten',vraag:'Hoe toon je aan welk deel van de schuld onder overgangsrecht valt?',antwoord:`Vraag bij de geldverstrekker een historisch overzicht op met de stand van de schuld op 31 december 2012. Leg daarnaast vast welke aflossingen en wijzigingen sindsdien zijn gedaan. Bij eerdere verhuizingen is ook de fiscale historie van vorige woningen nodig. Bewaar deze stukken blijvend in het dossier.`,tags:['overgangsrecht','bewijs','fiscale historie'],bron:''},
 {id:'hpx-008',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout met overgangsrecht bij een verhuizing naar een duurdere woning?',antwoord:`Een veelgemaakte fout is het extra leenbedrag ook als overgangsrecht aanmerken. Alleen het bestaande bedrag onder overgangsrecht kan aflossingsvrij mee. Het extra deel moet minimaal annuïtair in 360 maanden worden afgelost. Controleer ook of een eigenwoningreserve het overgangsrecht beperkt.`,tags:['overgangsrecht','verhuizen','fouten'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'hpx-009',thema:'hypotheek-producten',vraag:'Hoe lang blijft het overgangsrecht bewaard als een klant tijdelijk geen eigen woning heeft?',antwoord:`Het overgangsrecht blijft bewaard tot en met het einde van het jaar volgend op het jaar waarin de klant geen eigenwoningschuld meer had. Na die termijn vervalt het. Bij een latere aankoop gelden dan de regels voor nieuwe schulden. Controleer de exacte data aan de hand van de transportakten.`,tags:['overgangsrecht','tussenperiode','termijn'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'hpx-010',thema:'hypotheek-producten',vraag:'Wat is een spaarhypotheek en waarom kom je die nog tegen in de praktijk?',antwoord:`Bij een spaarhypotheek wordt niet tussentijds afgelost. De klant bouwt kapitaal op in een gekoppelde verzekering of rekening, waarmee de lening aan het eind wordt afgelost. Nieuwe spaarhypotheken met fiscale vrijstelling zijn sinds 2013 niet meer mogelijk. Bestaande polissen kunnen onder overgangsrecht vallen.`,tags:['spaarhypotheek','overgangsrecht','kapitaalverzekering'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'hpx-011',thema:'hypotheek-producten',vraag:'Waar let je op bij een lopende beleggingshypotheek die wordt overgesloten?',antwoord:`Beoordeel eerst of het opgebouwde kapitaal naar verwachting voldoende is om de lening af te lossen. Kijk ook naar de fiscale status van de polis en eventuele kosten bij afkoop of premievrij maken. Na de compensatieregelingen rond beleggingsverzekeringen is de verwachtingswaarde een vast gespreksonderwerp. Leg het verwachte tekort en de oplossing vast.`,tags:['beleggingshypotheek','oversluiten','kapitaaltekort'],bron:''},
 {id:'hpx-012',thema:'hypotheek-producten',vraag:'Wat is een bankspaarhypotheek?',antwoord:`Bij een bankspaarhypotheek spaart de klant op een geblokkeerde bankspaarrekening voor aflossing van de lening. De spaarrente is meestal gelijk aan de hypotheekrente. Nieuwe producten met fiscale vrijstelling zijn sinds 2013 niet meer afgesloten. Bestaande rekeningen vallen onder overgangsrecht als aan de voorwaarden wordt voldaan.`,tags:['bankspaarhypotheek','overgangsrecht','spaarrekening'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'hpx-013',thema:'hypotheek-producten',vraag:'Mag een overgangsrechtpolis of bankspaarrekening worden voortgezet bij een nieuwe geldverstrekker?',antwoord:`Een KEW, SEW of BEW kan in principe worden voortgezet bij oversluiten. De nieuwe geldverstrekker moet het product wel accepteren als zekerheid of gekoppeld product. Als dat niet kan, is overdracht naar een andere aanbieder soms een optie. Controleer de voorwaarden van zowel de oude als de nieuwe partij.`,tags:['KEW','BEW','oversluiten','overgangsrecht'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'hpx-014',thema:'hypotheek-producten',vraag:'Wat is een hybride hypotheek?',antwoord:`Een hybride hypotheek combineert sparen en beleggen binnen één product. De klant kan schuiven tussen spaar- en beleggingsdeel. Nieuwe hybride producten zijn zeldzaam. Bij bestaande hybride hypotheken let je vooral op kosten, het opgebouwde kapitaal en de fiscale status.`,tags:['hybride','spaardeel','beleggingsdeel'],bron:''},
 {id:'hpx-015',thema:'hypotheek-producten',vraag:'Hoe ga je om met een klant die een gemengde lening heeft met oude en nieuwe leningdelen?',antwoord:`Splits de analyse per leningdeel: overgangsrecht, nieuwe eigenwoningschuld en eventuele box 3-schuld. Elk deel kan andere fiscale gevolgen hebben bij aflossen of oversluiten. Gebruik een overzicht met per deel bedrag, aflosvorm, rentevaste periode en fiscale status. Dit voorkomt fouten bij latere wijzigingen.`,tags:['leningdelen','overgangsrecht','box 3','overzicht'],bron:''},
 {id:'hpx-016',thema:'hypotheek-producten',vraag:'Welke leningdelen los je bij extra aflossen bij voorkeur als eerste af?',antwoord:`Vaak is het verstandig eerst niet-aftrekbare leningdelen af te lossen, zoals box 3-schuld of consumptieve delen. Daarna komen delen met de hoogste rente of zonder fiscaal voordeel in beeld. Let op boetevrije ruimte per leningdeel en op het verlies van overgangsrecht bij aflossen van aflossingsvrije delen. Leg de keuze vast.`,tags:['extra aflossen','box 3','volgorde'],bron:''},
 {id:'hpx-017',thema:'hypotheek-producten',vraag:'Gaat overgangsrecht verloren als een klant op een aflossingsvrij deel extra aflost?',antwoord:`Het afgeloste bedrag verdwijnt definitief uit het overgangsrecht. Het kan later niet opnieuw aflossingsvrij worden geleend met renteaftrek. Bij een latere verhoging geldt de aflossingseis. Wijs de klant hierop voordat hij aflost op een oud aflossingsvrij deel.`,tags:['overgangsrecht','extra aflossen','aflossingsvrij'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'hpx-018',thema:'hypotheek-producten',vraag:'Kan een annuïteitenhypotheek met een looptijd korter dan 30 jaar worden afgesloten?',antwoord:`Ja, een kortere looptijd is toegestaan en voldoet aan de aflossingseis. De maandlast is dan hoger. Voor de hypotheektoets wordt meestal met een annuïteit over 30 jaar gerekend, maar de geldverstrekker kan anders toetsen. Controleer of de werkelijke maandlast past binnen het budget.`,tags:['annuïtair','looptijd','maandlast'],bron:''},
 {id:'hpx-019',thema:'hypotheek-producten',vraag:'Wat gebeurt er met de aflossingseis bij een verhoging van een bestaande hypotheek?',antwoord:`Het nieuwe deel van de eigenwoningschuld moet voldoen aan de aflossingseis. Dat betekent volledige aflossing in maximaal 360 maanden, minimaal annuïtair. Het bestaande deel houdt zijn eigen status. Maak per leningdeel duidelijk welke regels gelden.`,tags:['verhoging','aflossingseis','leningdelen'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-020',thema:'hypotheek-producten',vraag:'Hoe werkt de restant looptijd bij het omzetten van een oud leningdeel naar annuïtair?',antwoord:`Bij omzetten van een aflossingsvrij overgangsrechtdeel naar annuïtair kan de klant zelf een looptijd kiezen. Er geldt voor dat deel geen verplichte looptijd van 360 maanden vanaf een vaste datum. Het overgangsrecht vervalt wel voor het bedrag dat later wordt afgelost. Leg de afweging vast in het dossier.`,tags:['overgangsrecht','annuïtair','omzetten'],bron:''},
 {id:'hpx-021',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout bij het adviseren van een aflossingsvrij deel?',antwoord:`Een veelgemaakte fout is onvoldoende aandacht voor de situatie aan het eind van de looptijd. De schuld blijft dan volledig staan, terwijl het inkomen vaak lager is. Ook wordt de mogelijke herfinanciering op hoge leeftijd onderschat. Maak de eindsituatie concreet en leg de risicobespreking vast.`,tags:['aflossingsvrij','fouten','einde looptijd'],bron:''},
 {id:'hpx-022',thema:'hypotheek-producten',vraag:'Hoe bespreek je de situatie na de looptijd van een aflossingsvrije lening?',antwoord:`Laat zien wat er gebeurt als de schuld niet wordt afgelost. Bespreek opties als aflossen uit vermogen, verkoop, herfinanciering of een verzilverconstructie. Herfinanciering is niet gegarandeerd en hangt af van de voorwaarden op dat moment. Leg vast welke oplossing de klant voor ogen heeft.`,tags:['aflossingsvrij','einde looptijd','herfinanciering'],bron:''},
 {id:'hpx-023',thema:'hypotheek-producten',vraag:'Wanneer kan een geldverstrekker een aflossingsvrij deel opeisen?',antwoord:`Dat hangt af van de leningvoorwaarden. Sommige contracten kennen een einddatum of een leeftijdsgrens waarna de lening moet worden afgelost of verlengd. Andere kennen een onbepaalde looptijd. Controleer de voorwaarden van de geldverstrekker en de hypotheekakte.`,tags:['aflossingsvrij','looptijd','opeisbaarheid'],bron:''},
 {id:'hpx-024',thema:'hypotheek-producten',vraag:'Wat betekent een onbepaalde looptijd bij een aflossingsvrije lening?',antwoord:`Bij een onbepaalde looptijd is er geen vaste einddatum waarop de lening moet worden afgelost. De lening loopt door zolang de klant aan zijn verplichtingen voldoet. Bij verkoop of overlijden wordt de lening uit de opbrengst of nalatenschap afgelost. Het fiscale regime blijft afhankelijk van overgangsrecht en de 30-jaarstermijn.`,tags:['aflossingsvrij','onbepaalde looptijd','nalatenschap'],bron:''},
 {id:'hpx-025',thema:'hypotheek-producten',vraag:'Wat gebeurt er met de renteaftrek na 30 jaar bij een lening onder overgangsrecht?',antwoord:`Ook voor eigenwoningschuld onder overgangsrecht geldt een maximale aftrekperiode van 30 jaar. Voor schulden die op 31 december 2000 al bestonden, is die termijn gaan lopen per 1 januari 2001. Na afloop vervalt de aftrek, ook als de lening doorloopt. Controleer per leningdeel de startdatum van de aftrektermijn.`,tags:['renteaftrek','30 jaar','overgangsrecht'],bron:'Wet IB 2001'},
 {id:'hpx-026',thema:'hypotheek-producten',vraag:'Hoe adviseer je een klant die gaat aflossen maar ook buffer wil houden?',antwoord:`Weeg de rentebesparing af tegen het belang van vrij beschikbaar geld. Extra aflossen is meestal niet terug te halen zonder nieuwe financiering. Houd rekening met noodzakelijke reserves voor onderhoud, inkomensdaling en onverwachte uitgaven. Leg de gekozen buffer en de reden schriftelijk vast.`,tags:['extra aflossen','buffer','vastlegging'],bron:''},
 {id:'hpx-027',thema:'hypotheek-producten',vraag:'Wat is het verschil tussen aflossen met lagere maandlast en aflossen met kortere looptijd?',antwoord:`Na extra aflossen kan de geldverstrekker de maandlast herberekenen of de looptijd verkorten. Bij een lagere maandlast blijft de einddatum gelijk. Bij looptijdverkorting blijft de maandlast gelijk en is de klant eerder schuldenvrij. Niet elke geldverstrekker biedt beide keuzes, dus controleer de voorwaarden.`,tags:['extra aflossen','maandlast','looptijd'],bron:''},
 {id:'hpx-028',thema:'hypotheek-producten',vraag:'Mag een klant tussentijds extra aflossen op een lineair leningdeel?',antwoord:`Ja, dat is meestal mogelijk binnen de boetevrije ruimte. Bij lineair daalt daarna het vaste aflossingsbedrag of de looptijd, afhankelijk van de geldverstrekker. Boven de boetevrije ruimte kan een vergoeding voor vervroegde aflossing gelden. Controleer de voorwaarden van de geldverstrekker.`,tags:['lineair','extra aflossen','boetevrij'],bron:''},
 {id:'hpx-029',thema:'hypotheek-producten',vraag:'Hoe bespreek je het risico op een aflossingsachterstand bij een krappe annuïteit?',antwoord:`Bij een krappe annuïteit kan een kleine inkomensdaling al tot achterstand leiden. Bespreek welke buffer er is en welke regelingen de geldverstrekker kent. Wijs erop dat een achterstand fiscale gevolgen kan hebben als die niet tijdig wordt ingehaald. Leg het besproken risico vast.`,tags:['achterstand','annuïtair','buffer'],bron:''},
 {id:'hpx-030',thema:'hypotheek-producten',vraag:'Wat gebeurt er met de aflossingseis als een klant een achterstand oploopt?',antwoord:`Een betalingsachterstand leidt tot een achterstand ten opzichte van het annuïtaire schema. Of dit fiscale gevolgen heeft, hangt af van of en wanneer de achterstand wordt ingehaald. De wet kent hiervoor een inhaalregeling. Controleer de actuele regels bij de Belastingdienst en schakel tijdig de geldverstrekker in.`,tags:['achterstand','aflossingseis','herstel'],bron:'Belastingdienst'},
 {id:'hpx-031',thema:'hypotheek-producten',vraag:'Welke aflosvorm is gebruikelijk voor een restschuldfinanciering?',antwoord:`Een restschuldfinanciering wordt meestal annuïtair of lineair afgelost. Bij geldverstrekkers is de maximale looptijd voor restschuld vaak korter dan voor een woningfinanciering. Fiscaal geldt voor restschuld uit de periode 29 oktober 2012 tot en met 31 december 2017 een aftrektermijn van maximaal 15 jaar. Controleer de voorwaarden van de geldverstrekker.`,tags:['restschuld','aflosvorm','15 jaar'],bron:'Wet IB 2001'},
 {id:'hpx-032',thema:'hypotheek-producten',vraag:'Hoe kies je de aflosvorm voor een klant die over 15 jaar met pensioen gaat?',antwoord:`Bereken de maandlast ook na de pensioendatum. Een hoge resterende schuld bij pensionering kan de betaalbaarheid onder druk zetten. Overweeg lineair, een kortere looptijd of gericht extra aflossen. Leg de toekomstige inkomenssituatie en de gekozen oplossing vast.`,tags:['pensioen','aflosvorm','betaalbaarheid'],bron:''},
 {id:'hpx-033',thema:'hypotheek-producten',vraag:'Waarom kiezen sommige klanten bewust voor een deel box 3-schuld?',antwoord:`Een box 3-schuld kan passen als een klant flexibiliteit wil zonder aflossingsplicht. Denk aan klanten met veel vermogen of een bewuste vermogensplanning. De rente is niet aftrekbaar in box 1. De schuld kan wel invloed hebben op box 3, afhankelijk van de actuele regels. Leg de motivatie vast.`,tags:['box 3','aflossingsvrij','vermogensplanning'],bron:''},
 {id:'hpx-034',thema:'hypotheek-producten',vraag:'Hoe registreer je de aflossingseis bij de geldverstrekker?',antwoord:`De aflossingseis volgt uit het contractuele schema in de leningovereenkomst. Geef in de aanvraag per leningdeel de juiste aflosvorm en looptijd door. De geldverstrekker meldt jaarlijks gegevens aan de Belastingdienst. Controleer na passeren of de offerte en akte overeenkomen met het advies.`,tags:['aflossingseis','informatieplicht','controle'],bron:'Belastingdienst'},
 {id:'hpx-035',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout bij het splitsen van leningdelen?',antwoord:`Een veelgemaakte fout is het verkeerd toerekenen van het overgangsrecht aan leningdelen. Ook worden box 3-delen soms ten onrechte als aftrekbaar gepresenteerd. Leg per leningdeel de fiscale kwalificatie vast. Laat bij twijfel een fiscalist meekijken.`,tags:['leningdelen','overgangsrecht','fouten'],bron:''},
 {id:'hpx-036',thema:'hypotheek-producten',vraag:'Wat is het effect van een kortere looptijd op de netto maandlast?',antwoord:`Bij een kortere looptijd wordt sneller afgelost. De bruto maandlast stijgt en het rentedeel daalt sneller. Daardoor neemt ook het fiscale voordeel sneller af. Laat beide effecten zien in de berekening.`,tags:['looptijd','netto maandlast','annuïtair'],bron:''},
 {id:'hpx-037',thema:'hypotheek-producten',vraag:'Hoe ga je om met een klant die een lening wil met een looptijd langer dan 30 jaar?',antwoord:`Voor de eigenwoningschuld geldt een aflossing in maximaal 360 maanden. Een langere looptijd voldoet daar niet aan, waardoor de renteaftrek vervalt. Sommige geldverstrekkers bieden geen langere looptijd. Leg uit dat het niet past binnen de fiscale eisen.`,tags:['looptijd','aflossingseis','360 maanden'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-038',thema:'hypotheek-producten',vraag:'Wat betekent een herstart van de 360 maanden na oversluiten?',antwoord:`Bij oversluiten van een eigenwoningschuld loopt de oude aflossingstermijn door. De nieuwe lening moet worden afgelost binnen de resterende looptijd van de oorspronkelijke schuld. Een nieuwe termijn van 360 maanden geldt alleen voor een echte verhoging. Controleer de oorspronkelijke ingangsdatum.`,tags:['oversluiten','360 maanden','aflossingseis'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-039',thema:'hypotheek-producten',vraag:'Hoe documenteer je de fiscale historie bij oversluiten?',antwoord:`Vraag van de vorige geldverstrekker een overzicht van de leningdelen met startdatum, aflosvorm en restschuld. Leg ook vast welke delen onder overgangsrecht vallen en of er een eigenwoningreserve is. Bewaar deze stukken in het dossier. Ze zijn nodig bij latere wijzigingen of vragen van de Belastingdienst.`,tags:['oversluiten','fiscale historie','dossier'],bron:''},
 {id:'hpx-040',thema:'hypotheek-producten',vraag:'Waarom vraagt een betalingsvrije periode bij een lening extra fiscale aandacht?',antwoord:`Een periode zonder rente en aflossing wijkt af van een annuïtair schema. Of de lening dan toch eigenwoningschuld is, hangt af van de constructie en eventuele goedkeuringen van de Belastingdienst. Ga hier niet van uit op basis van de productnaam. Controleer de actuele voorwaarden en leg de fiscale kwalificatie vast.`,tags:['betalingsvrij','aflossingseis','eigenwoningschuld'],bron:'Belastingdienst'},
 {id:'hpx-041',thema:'hypotheek-producten',vraag:'Wat gebeurt er met de aflossingseis als een leningdeel wordt gesplitst in twee delen?',antwoord:`Splitsen verandert niets aan de oorspronkelijke ingangsdatum van de schuld. Beide nieuwe delen moeten samen binnen de resterende looptijd worden afgelost. Kies per deel een aflosvorm die minimaal annuïtair is. Leg de oorspronkelijke ingangsdatum per deel vast in het dossier.`,tags:['splitsen','aflossingseis','leningdelen'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-042',thema:'hypotheek-producten',vraag:'Hoe leg je een klant uit wat aflossingsvrij betekent voor de vermogensopbouw in de woning?',antwoord:`Bij een aflossingsvrij deel bouwt de klant geen vermogen op in de woning via aflossing. De overwaarde hangt dan volledig af van de waardeontwikkeling. Bij een waardedaling kan sneller een restschuld ontstaan. Maak dit concreet met een voorbeeld van stijgende en dalende waarde.`,tags:['aflossingsvrij','overwaarde','restschuld'],bron:''},
 {id:'hpx-043',thema:'hypotheek-producten',vraag:'Wat bespreek je met een klant die zijn aflossingsvrije deel wil omzetten bij het einde van de rentevaste periode?',antwoord:`Het einde van de rentevaste periode is vaak een kostenvrij moment om de aflosvorm te wijzigen. Bespreek de stijging van de maandlast en het mogelijke verlies van flexibiliteit. Toon de netto maandlast voor en na de wijziging. Leg de keuze en de redenen vast.`,tags:['aflossingsvrij','renteherziening','omzetten'],bron:''},
 {id:'hpx-044',thema:'hypotheek-producten',vraag:'Wat is een combinatie van annuïtair en aflossingsvrij in de praktijk?',antwoord:`Veel klanten hebben een deel annuïtair en een deel aflossingsvrij onder overgangsrecht. Daarmee blijft de maandlast lager dan bij volledige aflossing. Het aflossingsvrije deel blijft wel aan het eind staan. Bespreek of het restant aan het eind betaalbaar of aflosbaar is.`,tags:['combinatie','annuïtair','aflossingsvrij'],bron:''},
 {id:'hpx-045',thema:'hypotheek-producten',vraag:'Hoe bereken je een rekenvoorbeeld voor lineair aflossen?',antwoord:`Deel het leenbedrag door het aantal maanden om de vaste aflossing te bepalen. Bij een lening van 300.000 euro over 360 maanden is dat 833,33 euro per maand. Daarbij komt de rente over de openstaande schuld. Het voorbeeld is illustratief en niet afhankelijk van actuele tarieven.`,tags:['lineair','rekenvoorbeeld','aflossing'],bron:''},
 {id:'hpx-046',thema:'hypotheek-producten',vraag:'Waarom kan de netto maandlast bij lineair in het begin hoger uitvallen dan bij annuïtair?',antwoord:`Bij lineair is de bruto maandlast in het begin hoger door de vaste aflossing plus rente over de volledige schuld. Het renteaftrekvoordeel is in het begin vergelijkbaar. Daardoor is ook de netto maandlast hoger. Na verloop van tijd daalt de lineaire maandlast onder de annuïtaire.`,tags:['lineair','netto maandlast','vergelijking'],bron:''},
 {id:'hpx-047',thema:'hypotheek-producten',vraag:'Kan de aflosvorm worden gewijzigd zonder nieuwe hypotheekakte?',antwoord:`Dat is vaak mogelijk binnen dezelfde inschrijving, afhankelijk van de geldverstrekker. Een wijziging van aflosvorm verloopt meestal via een wijzigingsformulier. Een nieuwe akte is niet altijd nodig. Controleer de voorwaarden van de geldverstrekker en eventuele kosten.`,tags:['aflosvorm','wijziging','hypotheekakte'],bron:''},
 {id:'hpx-048',thema:'hypotheek-producten',vraag:'Hoe ga je om met een klant die tijdelijk minder wil aflossen?',antwoord:`Bekijk eerst of de geldverstrekker een tijdelijke regeling biedt. Let op de gevolgen voor de aflossingseis en de renteaftrek. Een tijdelijke betaalregeling moet vaak binnen een bepaalde periode worden hersteld. Leg de afspraak en de gevolgen vast in het dossier.`,tags:['betaalpauze','aflossingseis','tijdelijk'],bron:''},
 {id:'hpx-049',thema:'hypotheek-producten',vraag:'Wat zijn veelgemaakte fouten bij een nieuwe aflosvorm in het adviesrapport?',antwoord:`Veelgemaakte fouten zijn een onjuiste looptijd, het verkeerd doorgeven van de aflosvorm en het niet tonen van de netto maandlast over de looptijd. Ook ontbreekt soms de onderbouwing van de keuze. Controleer offerte, aanvraag en rapport op consistentie. Leg de verificatie vast.`,tags:['adviesrapport','fouten','controle'],bron:''},
 {id:'hpx-050',thema:'hypotheek-producten',vraag:'Wat zijn de gevolgen van een nieuwe aflosvorm voor de overlijdensrisicoverzekering?',antwoord:`Bij lineair of annuïtair daalt de schuld anders dan bij een aflossingsvrije lening. De dekking van een overlijdensrisicoverzekering kan daarop worden afgestemd, bijvoorbeeld gelijkblijvend, annuïtair of lineair dalend. Controleer of de dekking nog past bij de nieuwe situatie. Leg de afweging vast in het dossier.`,tags:['ORV','aflosvorm','dekking'],bron:''},
 {id:'hpx-051',thema:'hypotheek-producten',vraag:'Hoe werkt een daling naar een lagere risicoklasse tijdens de rentevaste periode?',antwoord:`Veel geldverstrekkers koppelen de renteopslag aan de verhouding tussen lening en woningwaarde. Daalt die verhouding door aflossing of waardestijging, dan kan de klant in een lagere risicoklasse vallen. Sommige geldverstrekkers passen dit automatisch toe bij aflossing, andere alleen op verzoek. Controleer de voorwaarden van de geldverstrekker.`,tags:['risicoklasse','LTV','renteopslag'],bron:''},
 {id:'hpx-052',thema:'hypotheek-producten',vraag:'Welke waardebepaling accepteert een geldverstrekker voor een lagere risicoklasse?',antwoord:`Dat verschilt per geldverstrekker. Soms volstaat de WOZ-waarde, soms is een gevalideerd taxatierapport of een modelmatige waardebepaling nodig. De kosten van een taxatie moeten opwegen tegen het rentevoordeel. Reken het voordeel uit voordat de klant een taxatie laat doen.`,tags:['risicoklasse','taxatie','WOZ-waarde'],bron:''},
 {id:'hpx-053',thema:'hypotheek-producten',vraag:'Kan de rente tijdens de rentevaste periode stijgen door een hogere risicoklasse?',antwoord:`In de regel blijft de rente tijdens de rentevaste periode gelijk of daalt deze alleen bij een lagere risicoklasse. Of een stijging mogelijk is, staat in de leningvoorwaarden. Bij een verhoging van de lening kan wel een nieuwe risicoklasse gelden voor het nieuwe deel. Controleer de voorwaarden van de geldverstrekker.`,tags:['risicoklasse','rentevast','voorwaarden'],bron:''},
 {id:'hpx-054',thema:'hypotheek-producten',vraag:'Hoe reken je uit of een taxatie voor een lagere risicoklasse loont?',antwoord:`Vermenigvuldig het renteverschil met de schuld en de resterende rentevaste periode. Trek daar de kosten van de taxatie en eventuele administratiekosten van af. Voorbeeld: 0,2 procent op 250.000 euro is 500 euro bruto per jaar. Houd ook rekening met het lagere renteaftrekvoordeel. De cijfers zijn illustratief.`,tags:['risicoklasse','rekenvoorbeeld','taxatie'],bron:''},
 {id:'hpx-055',thema:'hypotheek-producten',vraag:'Waarom kan de rente van een leningdeel met NHG lager zijn dan zonder NHG?',antwoord:`Met NHG loopt de geldverstrekker minder risico, omdat het Waarborgfonds Eigen Woningen borg staat. Dat vertaalt zich vaak in een lagere renteopslag. Bij veel geldverstrekkers geldt dan geen opslag voor de verhouding lening en woningwaarde. Weeg het rentevoordeel af tegen de eenmalige borgtochtprovisie.`,tags:['NHG','renteopslag','borgtochtprovisie'],bron:'NHG'},
 {id:'hpx-056',thema:'hypotheek-producten',vraag:'Wanneer kies je voor rentevaste periodes per leningdeel in plaats van één periode?',antwoord:`Spreiding van rentevaste periodes verkleint het risico dat de hele lening op een ongunstig moment wordt herzien. Het kan ook passen als de klant een deel binnenkort wil aflossen. Nadeel is meer complexiteit en soms een minder gunstige rente. Leg de afweging per leningdeel vast.`,tags:['rentevast','spreiding','leningdelen'],bron:''},
 {id:'hpx-057',thema:'hypotheek-producten',vraag:'Wat is het verband tussen de rentevaste periode en de toetsrente in de leennormen?',antwoord:`Bij een rentevaste periode van 10 jaar of langer mag de werkelijke rente worden gebruikt in de toets. Bij een kortere periode geldt de minimale toetsrente als die hoger is dan de werkelijke rente. Kies dus niet alleen op maandlast. Het actuele toetspercentage staat bij de AFM.`,tags:['toetsrente','rentevast','leennormen'],bron:'Trhk'},
 {id:'hpx-058',thema:'hypotheek-producten',vraag:'Wat is een plafondrente?',antwoord:`Bij een plafondrente is de rente variabel, maar kan deze niet boven een afgesproken maximum uitkomen. Daalt de marktrente, dan profiteert de klant mee. Voor deze zekerheid betaalt de klant meestal een opslag. Controleer de voorwaarden van de geldverstrekker, want dit product wordt niet overal aangeboden.`,tags:['plafondrente','variabele rente','opslag'],bron:''},
 {id:'hpx-059',thema:'hypotheek-producten',vraag:'Wanneer past een variabele rente bij een klant?',antwoord:`Variabele rente kan passen als de klant op korte termijn wil aflossen of verkopen. Ook bij een klant met voldoende buffer om rentestijgingen op te vangen kan het passen. Bij een smalle financiële marge is het risico vaak te groot. Leg vast hoe het renterisico is besproken.`,tags:['variabele rente','renterisico','buffer'],bron:''},
 {id:'hpx-060',thema:'hypotheek-producten',vraag:'Hoe vaak kan een variabele rente wijzigen?',antwoord:`Dat verschilt per geldverstrekker en staat in de voorwaarden. Vaak kan de variabele rente maandelijks of per kwartaal wijzigen. De geldverstrekker moet de klant tijdig informeren over wijzigingen. Controleer de voorwaarden van de geldverstrekker.`,tags:['variabele rente','wijziging','informatie'],bron:''},
 {id:'hpx-061',thema:'hypotheek-producten',vraag:'Kan een klant met variabele rente op elk moment boetevrij overstappen naar een vaste rente?',antwoord:`Bij de meeste geldverstrekkers kan een variabel leningdeel boetevrij worden omgezet naar een vaste rente. Ook boetevrij aflossen is bij variabele rente vaak mogelijk. Er kunnen wel administratiekosten gelden. Controleer de voorwaarden van de geldverstrekker.`,tags:['variabele rente','omzetten','boetevrij'],bron:''},
 {id:'hpx-062',thema:'hypotheek-producten',vraag:'Wat is rentebedenktijd?',antwoord:`Rentebedenktijd is een periode waarin de klant kan profiteren van een rentedaling na het uitbrengen van een renteaanbod. Komt de rente in die periode lager uit, dan geldt de lagere rente. Duur en voorwaarden verschillen per geldverstrekker. Het is ook bekend bij de renteverlenging aan het einde van de rentevaste periode.`,tags:['rentebedenktijd','rentedaling','renteaanbod'],bron:''},
 {id:'hpx-063',thema:'hypotheek-producten',vraag:'Wat gebeurt er als de klant niet reageert op het renteaanbod bij het einde van de rentevaste periode?',antwoord:`De geldverstrekker kiest dan een standaardoptie volgens de voorwaarden. Vaak is dat dezelfde rentevaste periode of een variabele rente. Dat is niet altijd de gunstigste keuze. Neem daarom tijdig contact op met de klant en leg de keuze vast.`,tags:['renteherziening','standaardoptie','nazorg'],bron:''},
 {id:'hpx-064',thema:'hypotheek-producten',vraag:'Mag een klant bij renteherziening ook de aflosvorm wijzigen?',antwoord:`Het einde van de rentevaste periode is vaak een goed moment om de aflosvorm te wijzigen. Fiscaal moet een eigenwoningschuld van na 2012 minimaal annuïtair blijven. Overgangsrecht kan verloren gaan bij omzetten naar een nieuwe structuur. Controleer de voorwaarden van de geldverstrekker.`,tags:['renteherziening','aflosvorm','overgangsrecht'],bron:''},
 {id:'hpx-065',thema:'hypotheek-producten',vraag:'Mag de geldverstrekker bij renteherziening een hogere opslag rekenen dan voor nieuwe klanten?',antwoord:`Geldverstrekkers hanteren vaak aparte tarieven voor bestaande klanten bij renteverlenging. Die kunnen afwijken van de tarieven voor nieuwe klanten. Vergelijk het verlengingsaanbod altijd met het actuele tarief van de geldverstrekker en met oversluiten. Leg de vergelijking vast in het dossier.`,tags:['renteherziening','tarieven','vergelijking'],bron:''},
 {id:'hpx-066',thema:'hypotheek-producten',vraag:'Kan een rentekorting voor een goed energielabel later nog worden toegekend of vervallen?',antwoord:`Sommige geldverstrekkers geven een rentekorting bij een goed energielabel. De korting kan afhangen van het label op het moment van aanvraag of van later aangeleverde labels. Controleer of de korting geldt voor de hele lening of voor een leningdeel. Controleer de voorwaarden van de geldverstrekker.`,tags:['energielabel','rentekorting','duurzaamheid'],bron:''},
 {id:'hpx-067',thema:'hypotheek-producten',vraag:'Wat is een rentekorting voor een betaalrekening bij dezelfde bank?',antwoord:`Sommige geldverstrekkers geven korting als de klant een betaalrekening bij hen aanhoudt. Vervalt de betaalrekening later, dan kan ook de korting vervallen. Neem deze voorwaarde mee in de vergelijking. Leg vast dat de klant hierover is geïnformeerd.`,tags:['rentekorting','betaalrekening','voorwaarden'],bron:''},
 {id:'hpx-068',thema:'hypotheek-producten',vraag:'Hoe leg je het renterisico vast in het adviesdossier?',antwoord:`Beschrijf welke rentevaste periode is gekozen en waarom. Neem een berekening op van de maandlast bij een hogere rente na afloop van de rentevaste periode. Leg vast hoe de klant het risico beoordeelt en welke buffer beschikbaar is. Dit ondersteunt de passendheid van het advies.`,tags:['renterisico','vastlegging','adviesdossier'],bron:''},
 {id:'hpx-069',thema:'hypotheek-producten',vraag:'Wat is een gangbaar rekenvoorbeeld voor een renteschok na afloop van de rentevaste periode?',antwoord:`Laat zien wat de maandlast wordt als de rente bijvoorbeeld 2 procentpunt hoger uitkomt. Gebruik de restschuld op het moment van renteherziening. Toon zowel bruto als netto maandlast. Het voorbeeld is illustratief en niet gebaseerd op actuele tarieven.`,tags:['renteschok','rekenvoorbeeld','maandlast'],bron:''},
 {id:'hpx-070',thema:'hypotheek-producten',vraag:'Kan een geldverstrekker de variabele rente zomaar verhogen?',antwoord:`De voorwaarden bepalen hoe de variabele rente wordt vastgesteld. De geldverstrekker moet de rente op een redelijke en transparante manier aanpassen. Klachten over de hoogte van variabele rente kunnen bij Kifid worden voorgelegd. Leg vast welke informatie de klant over de rentewijziging heeft gekregen.`,tags:['variabele rente','Kifid','transparantie'],bron:'Kifid'},
 {id:'hpx-071',thema:'hypotheek-producten',vraag:'Wat is het verschil tussen de rente op het moment van offerte en op het moment van passeren?',antwoord:`Veel geldverstrekkers hanteren de laagste van de offerterente en de rente op passeerdatum. Andere hanteren alleen de offerterente of de dagrente. Dit staat in de offertevoorwaarden. Controleer dit vooraf en informeer de klant.`,tags:['offerterente','passeerdatum','laagste rente'],bron:''},
 {id:'hpx-072',thema:'hypotheek-producten',vraag:'Waarom kan een langere rentevaste periode toch passend zijn bij een hogere rente?',antwoord:`Een langere rentevaste periode geeft zekerheid over de maandlast. Dat is vooral belangrijk bij een krappe financiering of een gezin met weinig buffer. De hogere rente is de prijs voor die zekerheid. Leg vast waarom zekerheid zwaarder weegt.`,tags:['rentevast','zekerheid','passendheid'],bron:''},
 {id:'hpx-073',thema:'hypotheek-producten',vraag:'Waar let je op bij een rentevaste periode die langer is dan de verwachte woonduur?',antwoord:`Bij een verwachte verhuizing kan een lange rentevaste periode tot een vergoeding voor vervroegde aflossing leiden. Een verhuisregeling kan dat beperken. Bij verkoop is aflossen vaak boetevrij. Controleer de voorwaarden van de geldverstrekker en leg de verwachte woonduur vast.`,tags:['rentevast','woonduur','verhuizen'],bron:''},
 {id:'hpx-074',thema:'hypotheek-producten',vraag:'Kun je rentevaste periodes van meerdere leningdelen laten samenvallen?',antwoord:`Bij een nieuwe financiering kan dat door alle delen dezelfde periode te geven. Bij lopende leningdelen kan het via renteherziening op een bepaald moment, maar dan kan een vergoeding voor vervroegde aflossing gelden. Samenvallen maakt de lening overzichtelijker. Het vergroot wel het risico op een ongunstig moment.`,tags:['rentevast','leningdelen','samenvallen'],bron:''},
 {id:'hpx-075',thema:'hypotheek-producten',vraag:'Hoe ga je om met een rente-opslag voor aflossingsvrije leningdelen?',antwoord:`Sommige geldverstrekkers rekenen een opslag voor aflossingsvrije delen. Dat verhoogt de kosten van flexibiliteit. Vergelijk de kosten met de alternatieven en leg de afweging vast. Controleer de voorwaarden van de geldverstrekker.`,tags:['aflossingsvrij','renteopslag','kosten'],bron:''},
 {id:'hpx-076',thema:'hypotheek-producten',vraag:'Wat is de invloed van de rentevaste periode op de overlijdensrisicoverzekering?',antwoord:`Er is geen directe koppeling, maar een kortere rentevaste periode verhoogt het risico op hogere lasten. Een nabestaande moet die lasten ook kunnen dragen. Neem dit mee bij het bepalen van de dekking. Leg de afweging vast.`,tags:['ORV','rentevast','nabestaanden'],bron:''},
 {id:'hpx-077',thema:'hypotheek-producten',vraag:'Hoe informeer je een klant over de rentevergelijking bij meerdere geldverstrekkers?',antwoord:`Vergelijk op gelijke voorwaarden: dezelfde rentevaste periode, aflosvorm, risicoklasse en kortingen. Neem ook verschillen in voorwaarden mee, zoals verhuisregeling en boetevrije aflossing. Laat zien waarom een geldverstrekker is gekozen. Leg de vergelijking vast in het dossier.`,tags:['rentevergelijking','geldverstrekkers','voorwaarden'],bron:''},
 {id:'hpx-078',thema:'hypotheek-producten',vraag:'Wat zijn veelgemaakte fouten bij het kiezen van een rentevaste periode?',antwoord:`Veelgemaakte fouten zijn alleen kijken naar de laagste rente en de woonduur niet bespreken. Ook wordt soms de toets met de toetsrente vergeten. Een andere fout is de rentevaste periode niet afstemmen op de buffer van de klant. Leg de afweging per factor vast.`,tags:['rentevast','fouten','keuze'],bron:''},
 {id:'hpx-079',thema:'hypotheek-producten',vraag:'Wat is een rentevaste periode van 20 of 30 jaar en waar let je op?',antwoord:`Een zeer lange rentevaste periode geeft maximale zekerheid. De rente is vaak hoger dan bij kortere periodes. Een vergoeding voor vervroegde aflossing kan bij oversluiten hoog uitvallen. Controleer de voorwaarden rond verhuizen en boetevrij aflossen.`,tags:['rentevast','lange periode','vergoeding'],bron:''},
 {id:'hpx-080',thema:'hypotheek-producten',vraag:'Wat is het verschil tussen een rentevaste periode en een rentebedenktijd bij de verlenging?',antwoord:`De rentevaste periode is de periode waarvoor de rente vastligt. De rentebedenktijd is een korte periode waarin de klant nog van een rentedaling kan profiteren. Ze worden soms verward. Leg in het dossier vast welke afspraak geldt.`,tags:['rentevast','rentebedenktijd','verschil'],bron:''},
 {id:'hpx-081',thema:'hypotheek-producten',vraag:'Hoe werkt rentemiddeling rekenkundig in hoofdlijnen?',antwoord:`Bij rentemiddeling wordt de lopende rentevaste periode voortijdig beëindigd. De vergoeding voor vervroegde aflossing wordt niet ineens betaald, maar verwerkt in een opslag op de nieuwe rente. De nieuwe rente ligt daardoor tussen de oude contractrente en de actuele marktrente. De precieze rekenmethode verschilt per geldverstrekker.`,tags:['rentemiddeling','opslag','berekening'],bron:''},
 {id:'hpx-082',thema:'hypotheek-producten',vraag:'Is een geldverstrekker verplicht rentemiddeling aan te bieden?',antwoord:`Nee, rentemiddeling is geen wettelijk recht van de klant. Geldverstrekkers bepalen zelf of en onder welke voorwaarden ze het aanbieden. De voorwaarden kunnen in de tijd wijzigen. Controleer de actuele voorwaarden van de geldverstrekker.`,tags:['rentemiddeling','verplichting','voorwaarden'],bron:''},
 {id:'hpx-083',thema:'hypotheek-producten',vraag:'In welke situaties pakt rentemiddeling vaak nadelig uit?',antwoord:`Rentemiddeling is minder gunstig als de resterende rentevaste periode kort is. Het voordeel is dan beperkt, terwijl de nieuwe periode lang kan zijn. Ook bij een verwachte verhuizing of aflossing kan het nadelig uitpakken. Reken altijd de totale rentelasten door en leg de vergelijking vast.`,tags:['rentemiddeling','nadelen','resterende periode'],bron:''},
 {id:'hpx-084',thema:'hypotheek-producten',vraag:'Waar let je op bij de opslag bij rentemiddeling?',antwoord:`De opslag is de vergoeding voor vervroegde aflossing omgezet in een rente-opslag. Vraag de geldverstrekker om een specificatie van de opslag. Sommige geldverstrekkers rekenen ook een extra risico-opslag. Bij een opslag die niet goed is toegelicht, is extra voorzichtigheid geboden.`,tags:['rentemiddeling','opslag','transparantie'],bron:''},
 {id:'hpx-085',thema:'hypotheek-producten',vraag:'Hoe vergelijk je rentemiddeling met oversluiten?',antwoord:`Bij oversluiten betaalt de klant de vergoeding voor vervroegde aflossing ineens en sluit hij een nieuwe lening af. Bij rentemiddeling wordt de vergoeding in de nieuwe rente verwerkt. Vergelijk de totale lasten over dezelfde periode, inclusief advies-, notaris- en taxatiekosten. Leg beide scenarios vast.`,tags:['rentemiddeling','oversluiten','vergelijking'],bron:''},
 {id:'hpx-086',thema:'hypotheek-producten',vraag:'Heeft rentemiddeling gevolgen voor de verhuisregeling?',antwoord:`Na rentemiddeling geldt een nieuwe rente en vaak een nieuwe rentevaste periode. De verhuisregeling geldt dan voor die nieuwe rente. Bij een verhuizing kan het voordeel van de middeling dus meegaan, maar ook de opslag. Controleer de voorwaarden van de geldverstrekker.`,tags:['rentemiddeling','verhuisregeling','opslag'],bron:''},
 {id:'hpx-087',thema:'hypotheek-producten',vraag:'Is de opslag bij rentemiddeling fiscaal aftrekbaar?',antwoord:`De opslag maakt deel uit van de rente en is in de regel aftrekbaar voor een eigenwoningschuld. Dat verschilt van een vergoeding die ineens wordt betaald, die ook aftrekbaar is maar in één jaar. Controleer het actuele standpunt van de Belastingdienst. Laat bij twijfel een fiscalist meekijken.`,tags:['rentemiddeling','renteaftrek','opslag'],bron:'Belastingdienst'},
 {id:'hpx-088',thema:'hypotheek-producten',vraag:'Wat is de rol van de klachtinstantie bij rentemiddeling?',antwoord:`Er zijn klachten bij Kifid ingediend over de informatieverstrekking bij rentemiddeling. Daarin speelde vooral of de klant voldoende inzicht had in de opslag. Dat onderstreept het belang van een heldere toelichting. Leg vast welke informatie de klant heeft ontvangen.`,tags:['rentemiddeling','Kifid','informatieplicht'],bron:'Kifid'},
 {id:'hpx-089',thema:'hypotheek-producten',vraag:'Wat leg je vast bij een advies over rentemiddeling?',antwoord:`Leg de oude rente, de nieuwe rente, de opslag en de nieuwe rentevaste periode vast. Neem een vergelijking op met doorlopen tot het einde van de periode en met oversluiten. Beschrijf de verwachte woonduur en aflosplannen. Leg vast welke keuze de klant maakt en waarom.`,tags:['rentemiddeling','vastlegging','vergelijking'],bron:''},
 {id:'hpx-090',thema:'hypotheek-producten',vraag:'Kan rentemiddeling per leningdeel worden toegepast?',antwoord:`Bij veel geldverstrekkers kan rentemiddeling per leningdeel. Dat maakt een gerichte keuze mogelijk voor delen met de hoogste rente. Let op de gevolgen voor de spreiding van rentevaste periodes. Controleer de voorwaarden van de geldverstrekker.`,tags:['rentemiddeling','leningdelen','spreiding'],bron:''},
 {id:'hpx-091',thema:'hypotheek-producten',vraag:'Wat gebeurt er bij vervroegde aflossing na rentemiddeling?',antwoord:`Na rentemiddeling geldt de nieuwe rente als contractrente. Een vergoeding voor vervroegde aflossing wordt dan over deze nieuwe rente berekend. Doordat de opslag in de rente zit, kan aflossen alsnog tot een vergoeding leiden. Controleer de voorwaarden van de geldverstrekker.`,tags:['rentemiddeling','vervroegde aflossing','contractrente'],bron:''},
 {id:'hpx-092',thema:'hypotheek-producten',vraag:'Waarom kan de nieuwe rente na rentemiddeling hoger zijn dan verwacht?',antwoord:`De nieuwe rente bevat de vergoeding voor vervroegde aflossing en soms een extra opslag. Als de rentevaste periode na middeling lang is, wordt de vergoeding over meer jaren verdeeld. Daarnaast speelt de actuele marktrente voor de nieuwe periode mee. Vraag een specificatie op.`,tags:['rentemiddeling','opslag','specificatie'],bron:''},
 {id:'hpx-093',thema:'hypotheek-producten',vraag:'Kan rentemiddeling helpen bij betaalbaarheidsproblemen?',antwoord:`Rentemiddeling kan de maandlast direct verlagen als de marktrente lager is dan de contractrente. Dat kan helpen bij een krap budget. Het lost echter niet altijd het onderliggende probleem op. Bespreek ook andere oplossingen en leg de afweging vast.`,tags:['rentemiddeling','betalingsproblemen','maandlast'],bron:''},
 {id:'hpx-094',thema:'hypotheek-producten',vraag:'Mag een adviseur rentemiddeling adviseren zonder vergelijking met oversluiten?',antwoord:`Een zorgvuldig advies bevat een vergelijking met realistische alternatieven. Oversluiten hoort daar meestal bij, ook als het niet de voorkeur heeft. Leg vast waarom een alternatief niet geschikt is. Dat beschermt de klant en de adviseur.`,tags:['rentemiddeling','zorgplicht','alternatieven'],bron:'Wft'},
 {id:'hpx-095',thema:'hypotheek-producten',vraag:'Wat is een rekenvoorbeeld van rentemiddeling?',antwoord:`Stel: lening 200.000 euro, contractrente 4 procent, marktrente 3 procent, nog 5 jaar rentevast. Het rentenadeel voor de geldverstrekker is ongeveer 1 procent per jaar over 5 jaar. Bij middeling over 10 jaar wordt dat nadeel verdeeld, wat een opslag van ongeveer 0,5 procent geeft. De nieuwe rente komt dan rond 3,5 procent, zonder contante waarde en extra opslag. Illustratief.`,tags:['rentemiddeling','rekenvoorbeeld','opslag'],bron:''},
 {id:'hpx-096',thema:'hypotheek-producten',vraag:'Waarom is de looptijd van de nieuwe rentevaste periode belangrijk bij rentemiddeling?',antwoord:`Hoe langer de nieuwe periode, hoe meer jaren de opslag wordt verdeeld. Dat verlaagt de opslag per jaar, maar verlengt de periode met opslag. Een kortere periode leidt tot een hogere opslag. Laat beide varianten zien.`,tags:['rentemiddeling','rentevast','opslag'],bron:''},
 {id:'hpx-097',thema:'hypotheek-producten',vraag:'Kan de klant na rentemiddeling alsnog overstappen naar een andere geldverstrekker?',antwoord:`Dat kan, maar dan geldt een vergoeding voor vervroegde aflossing over de nieuwe rente. De opslag uit de middeling werkt daarbij door. Overstappen kort na middeling is daardoor vaak ongunstig. Leg vast dat de klant hierover is geïnformeerd.`,tags:['rentemiddeling','oversluiten','vergoeding'],bron:''},
 {id:'hpx-098',thema:'hypotheek-producten',vraag:'Hoe gaat een geldverstrekker om met de marktrente bij rentemiddeling?',antwoord:`De geldverstrekker gebruikt de actuele rente voor de nieuwe rentevaste periode. Daarbij gelden de eigen tarieven, risicoklasse en kortingen. Dit verschilt per geldverstrekker. Controleer de voorwaarden van de geldverstrekker.`,tags:['rentemiddeling','marktrente','tarieven'],bron:''},
 {id:'hpx-099',thema:'hypotheek-producten',vraag:'Wat zijn veelgemaakte fouten bij rentemiddeling?',antwoord:`Veelgemaakte fouten zijn alleen naar de lagere maandlast kijken en de totale lasten negeren. Ook wordt de opslag niet altijd gespecificeerd. Een andere fout is geen vergelijking met oversluiten of doorlopen. Leg alle scenarios en de keuze vast.`,tags:['rentemiddeling','fouten','vastlegging'],bron:''},
 {id:'hpx-100',thema:'hypotheek-producten',vraag:'Wat is het verschil tussen rentemiddeling en renteverlenging vooraf?',antwoord:`Bij renteverlenging vooraf wordt de nieuwe rente vastgelegd vóór het einde van de lopende periode. De oude rente blijft tot dat einde gelden. Bij rentemiddeling wordt de lopende periode direct beëindigd en wordt de vergoeding in de nieuwe rente verwerkt. Het risico en de kosten verschillen dus.`,tags:['rentemiddeling','renteverlenging vooraf','verschil'],bron:''},
 {id:'hpx-101',thema:'hypotheek-producten',vraag:'Mag de vergoeding voor vervroegde aflossing hoger zijn dan het nadeel van de geldverstrekker?',antwoord:`Nee, de vergoeding mag niet hoger zijn dan het financiële nadeel dat de geldverstrekker lijdt. Dit volgt uit de regels voor hypothecair krediet. De AFM heeft in een leidraad uitgewerkt hoe dat nadeel redelijk wordt berekend. Controleer bij twijfel de berekening van de geldverstrekker.`,tags:['vergoeding vervroegde aflossing','nadeel','AFM'],bron:'AFM'},
 {id:'hpx-102',thema:'hypotheek-producten',vraag:'Welke elementen bevat een correcte berekening van de vergoeding voor vervroegde aflossing?',antwoord:`Een correcte berekening houdt rekening met:
- het renteverschil tussen contractrente en vergelijkingsrente;
- het bedrag boven de boetevrije ruimte;
- de resterende rentevaste periode;
- contante waarde van het rentenadeel.
Vraag bij twijfel een specificatie op bij de geldverstrekker.`,tags:['vergoeding vervroegde aflossing','berekening','contante waarde'],bron:'AFM'},
 {id:'hpx-103',thema:'hypotheek-producten',vraag:'Wat is de vergelijkingsrente bij de berekening van een vergoeding voor vervroegde aflossing?',antwoord:`De vergelijkingsrente is de actuele rente van de geldverstrekker voor een periode die aansluit bij de resterende rentevaste periode. Welke rente precies wordt gebruikt, staat in de voorwaarden. Sommige geldverstrekkers gebruiken de rente zonder kortingen of met een vaste risicoklasse. Controleer de voorwaarden van de geldverstrekker.`,tags:['vergelijkingsrente','vergoeding vervroegde aflossing','voorwaarden'],bron:''},
 {id:'hpx-104',thema:'hypotheek-producten',vraag:'Wat is een rekenvoorbeeld van een vergoeding voor vervroegde aflossing?',antwoord:`Stel: aflossing van 150.000 euro, contractrente 4 procent, vergelijkingsrente 3 procent en nog 4 jaar rentevast. Het jaarlijkse rentenadeel is 1 procent van 150.000 euro, dus 1.500 euro. Over 4 jaar is dat 6.000 euro, vóór contant maken en zonder boetevrije ruimte. De werkelijke vergoeding is lager door contante waarde en boetevrije ruimte. Illustratief.`,tags:['rekenvoorbeeld','vergoeding vervroegde aflossing','rentenadeel'],bron:''},
 {id:'hpx-105',thema:'hypotheek-producten',vraag:'Waarom kan de vergoeding voor vervroegde aflossing per dag veranderen?',antwoord:`De vergoeding hangt af van de actuele vergelijkingsrente en de resterende rentevaste periode. Beide veranderen in de tijd. Een daling van de marktrente verhoogt de vergoeding. Vraag daarom een actuele berekening vlak voor het besluit en leg de datum vast.`,tags:['vergoeding vervroegde aflossing','marktrente','actualiteit'],bron:''},
 {id:'hpx-106',thema:'hypotheek-producten',vraag:'Geldt de boetevrije ruimte ook bij volledig oversluiten?',antwoord:`Veel geldverstrekkers houden bij de berekening rekening met de boetevrije ruimte van dat jaar. Dat verlaagt de vergoeding. Of dit gebeurt en hoe, staat in de voorwaarden. Controleer de voorwaarden van de geldverstrekker.`,tags:['boetevrije ruimte','oversluiten','vergoeding vervroegde aflossing'],bron:''},
 {id:'hpx-107',thema:'hypotheek-producten',vraag:'Is boetevrije ruimte die een klant niet gebruikt over te hevelen naar het volgende jaar?',antwoord:`In de regel niet. De boetevrije ruimte geldt per kalenderjaar en vervalt als die niet wordt gebruikt. Sommige geldverstrekkers hanteren een andere systematiek. Controleer de voorwaarden van de geldverstrekker.`,tags:['boetevrije ruimte','kalenderjaar','voorwaarden'],bron:''},
 {id:'hpx-108',thema:'hypotheek-producten',vraag:'Is de boetevrije ruimte gebaseerd op de oorspronkelijke hoofdsom of de restschuld?',antwoord:`Dat verschilt per geldverstrekker. Sommige rekenen met de oorspronkelijke hoofdsom, andere met de actuele restschuld. Dat kan een groot verschil maken bij een oudere lening. Controleer de voorwaarden van de geldverstrekker.`,tags:['boetevrije ruimte','hoofdsom','restschuld'],bron:''},
 {id:'hpx-109',thema:'hypotheek-producten',vraag:'Tellen reguliere aflossingen mee voor de boetevrije ruimte?',antwoord:`Bij veel geldverstrekkers tellen contractuele aflossingen niet mee voor de boetevrije ruimte. Bij sommige wel. Dat beïnvloedt hoeveel een klant extra kan aflossen zonder vergoeding. Controleer de voorwaarden van de geldverstrekker.`,tags:['boetevrije ruimte','reguliere aflossing','voorwaarden'],bron:''},
 {id:'hpx-110',thema:'hypotheek-producten',vraag:'Is aflossing bij overlijden van een van de kredietnemers boetevrij?',antwoord:`Bij veel geldverstrekkers is aflossing na overlijden boetevrij, bijvoorbeeld uit een uitkering van een overlijdensrisicoverzekering. Er geldt vaak een termijn waarbinnen moet worden afgelost. Controleer de voorwaarden van de geldverstrekker.`,tags:['overlijden','boetevrij','ORV'],bron:''},
 {id:'hpx-111',thema:'hypotheek-producten',vraag:'In welk jaar komt een ineens betaalde vergoeding voor vervroegde aflossing in aftrek?',antwoord:`Een ineens betaalde vergoeding bij oversluiten van een eigenwoningschuld komt in de regel in aftrek in het jaar van betaling. Dat kan in dat jaar een groot aftrekbedrag opleveren. Houd rekening met het tarief waartegen de aftrek plaatsvindt. Controleer het actuele standpunt van de Belastingdienst.`,tags:['vergoeding vervroegde aflossing','aftrekjaar','oversluiten'],bron:'Belastingdienst'},
 {id:'hpx-112',thema:'hypotheek-producten',vraag:'Is de rente op een meegefinancierde vergoeding voor vervroegde aflossing aftrekbaar?',antwoord:`Wordt de vergoeding meegefinancierd in de nieuwe lening, dan is dat deel geen eigenwoningschuld. De rente over dat deel is dan niet aftrekbaar in box 1. Het deel valt in de regel in box 3. Leg de splitsing per leningdeel vast.`,tags:['meefinancieren','vergoeding vervroegde aflossing','box 3'],bron:'Belastingdienst'},
 {id:'hpx-113',thema:'hypotheek-producten',vraag:'Hoe bereken je het terugverdienmoment van oversluiten?',antwoord:`Tel alle kosten van oversluiten op: vergoeding, advies, notaris, taxatie en eventuele borgtochtprovisie. Bereken het maandelijkse rentevoordeel na belasting. Deel de kosten door het netto maandvoordeel. Het resultaat is het aantal maanden tot het terugverdienmoment.`,tags:['oversluiten','terugverdientijd','kosten'],bron:''},
 {id:'hpx-114',thema:'hypotheek-producten',vraag:'Welke kosten worden vaak vergeten bij oversluiten?',antwoord:`Vaak vergeten zijn taxatiekosten, kosten voor een nieuwe hypotheekakte en royement, bereidstellingsprovisie bij lange trajecten en eventuele afsluitkosten van de nieuwe geldverstrekker. Ook de kosten voor wijziging van gekoppelde verzekeringen worden soms vergeten. Neem alle posten op in het overzicht.`,tags:['oversluiten','kosten','overzicht'],bron:''},
 {id:'hpx-115',thema:'hypotheek-producten',vraag:'Mogen de kosten van oversluiten worden meegefinancierd als eigenwoningschuld?',antwoord:`Kosten van oversluiten zijn geen uitgaven voor verwerving, verbetering of onderhoud van de woning. Een meegefinancierd deel daarvoor is in de regel geen eigenwoningschuld. De kosten zelf kunnen wel aftrekbaar zijn als financieringskosten. Controleer het actuele standpunt van de Belastingdienst.`,tags:['oversluiten','financieringskosten','eigenwoningschuld'],bron:'Belastingdienst'},
 {id:'hpx-116',thema:'hypotheek-producten',vraag:'Wat is een aflosnota en waarom is die belangrijk bij oversluiten?',antwoord:`De aflosnota is een opgave van de vorige geldverstrekker van het bedrag dat nodig is om de lening af te lossen. Daarin staan restschuld, rente tot passeerdatum en eventuele vergoeding. De notaris gebruikt de nota voor de afwikkeling. Controleer de nota tijdig op juistheid.`,tags:['aflosnota','notaris','oversluiten'],bron:''},
 {id:'hpx-117',thema:'hypotheek-producten',vraag:'Wat gebeurt er met de oude hypotheekinschrijving na oversluiten?',antwoord:`Na aflossing van de oude lening laat de notaris de oude hypotheekinschrijving doorhalen. Dit heet royement. Daarvoor worden kosten in rekening gebracht. De nieuwe geldverstrekker krijgt een eigen hypotheekrecht.`,tags:['royement','hypotheekakte','notaris'],bron:''},
 {id:'hpx-118',thema:'hypotheek-producten',vraag:'Welke stukken heeft de nieuwe geldverstrekker nodig om overgangsrecht bij oversluiten correct over te nemen?',antwoord:`De nieuwe geldverstrekker heeft gegevens nodig over de oorspronkelijke schuld, de stand op 31 december 2012 en eventuele gekoppelde polissen of rekeningen. Ook de startdatum van het aflosschema per leningdeel is relevant. Zonder deze gegevens kan een leningdeel verkeerd worden gekwalificeerd. Controleer de verwerking in de offerte.`,tags:['overgangsrecht','oversluiten','stukken'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'hpx-119',thema:'hypotheek-producten',vraag:'Mag de looptijd bij oversluiten worden verlengd?',antwoord:`Fiscaal moet een eigenwoningschuld van na 2012 worden afgelost binnen de resterende looptijd van de oorspronkelijke 360 maanden. Een langere looptijd leidt tot verlies van renteaftrek over het deel dat niet tijdig wordt afgelost. Een geldverstrekker kan contractueel wel ruimer zijn. Leg de fiscale gevolgen vast.`,tags:['oversluiten','looptijd','aflossingseis'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-120',thema:'hypotheek-producten',vraag:'Hoe ga je om met een klant die wil oversluiten met NHG?',antwoord:`Oversluiten met NHG is onder voorwaarden mogelijk. De lening moet passen binnen de NHG-normen en de actuele kostengrens. Er kan een borgtochtprovisie gelden. Controleer de voorwaarden van NHG.`,tags:['NHG','oversluiten','voorwaarden'],bron:'NHG'},
 {id:'hpx-121',thema:'hypotheek-producten',vraag:'Wanneer is intern omzetten voordeliger dan extern oversluiten?',antwoord:`Intern omzetten kan voordelig zijn als de eigen geldverstrekker een redelijk aanbod doet. De notaris- en taxatiekosten vallen dan vaak weg. Extern oversluiten kan voordeliger zijn bij een groot renteverschil. Vergelijk beide scenarios en leg de keuze vast.`,tags:['intern omzetten','oversluiten','vergelijking'],bron:''},
 {id:'hpx-122',thema:'hypotheek-producten',vraag:'Wat zijn veelgemaakte fouten bij het oversluiten van een hypotheek?',antwoord:`Veelgemaakte fouten zijn het vergeten van fiscale gevolgen en het meefinancieren van niet-aftrekbare kosten zonder dit te benoemen. Ook wordt de resterende looptijd soms onjuist overgenomen. Een andere fout is gekoppelde verzekeringen niet aanpassen. Controleer elk onderdeel en leg het vast.`,tags:['oversluiten','fouten','fiscale gevolgen'],bron:''},
 {id:'hpx-123',thema:'hypotheek-producten',vraag:'Kan een klant oversluiten als de woningwaarde is gedaald?',antwoord:`Dat kan, maar een hogere LTV kan leiden tot een hogere risicoklasse. Bij een LTV boven het maximum zijn de mogelijkheden beperkt. De Trhk biedt ruimte voor oversluiten van een bestaande lening zonder verhoging. Controleer de voorwaarden van de geldverstrekker.`,tags:['oversluiten','woningwaarde','LTV'],bron:'Trhk'},
 {id:'hpx-124',thema:'hypotheek-producten',vraag:'Wat is het verschil tussen een vergoeding bij gedeeltelijke en bij volledige aflossing?',antwoord:`Bij gedeeltelijke aflossing geldt de vergoeding alleen over het bedrag boven de boetevrije ruimte. Bij volledige aflossing zonder vrijstellingsgrond geldt de vergoeding over het hele bedrag minus de boetevrije ruimte. De berekening is verder vergelijkbaar. Controleer de voorwaarden van de geldverstrekker.`,tags:['gedeeltelijke aflossing','volledige aflossing','vergoeding'],bron:''},
 {id:'hpx-125',thema:'hypotheek-producten',vraag:'Hoe ga je om met een klant die de vergoeding als onredelijk ervaart?',antwoord:`Vraag een specificatie van de berekening op. Controleer of de juiste vergelijkingsrente, boetevrije ruimte en contante waarde zijn gebruikt. Bij onduidelijkheid kan de klant een klacht indienen bij de geldverstrekker en daarna bij Kifid. Leg de stappen vast.`,tags:['vergoeding vervroegde aflossing','klacht','Kifid'],bron:'Kifid'},
 {id:'hpx-126',thema:'hypotheek-producten',vraag:'Wat is een veelvoorkomende misvatting over boetevrij aflossen bij verkoop?',antwoord:`Een misvatting is dat elke verkoop altijd boetevrij is. Bij veel geldverstrekkers geldt dat alleen bij verkoop aan een derde en verhuizing van de klant. Verkoop binnen de familie of aan een eigen bv kan anders worden behandeld. Controleer de voorwaarden van de geldverstrekker.`,tags:['verkoop','boetevrij','misvatting'],bron:''},
 {id:'hpx-127',thema:'hypotheek-producten',vraag:'Is aflossen bij een scheiding boetevrij?',antwoord:`Dat hangt af van de situatie en de voorwaarden. Bij verkoop aan een derde is aflossing vaak boetevrij. Bij overname door een van de partners met aflossing of herfinanciering kan een vergoeding gelden. Controleer de voorwaarden van de geldverstrekker.`,tags:['scheiding','boetevrij','overname'],bron:''},
 {id:'hpx-128',thema:'hypotheek-producten',vraag:'Kan een vergoeding voor vervroegde aflossing ontstaan bij een verhoging?',antwoord:`Bij een verhoging bij dezelfde geldverstrekker blijft de bestaande lening meestal staan. Er ontstaat dan geen vergoeding. Bij een volledige herfinanciering bij een andere geldverstrekker wel. Controleer de voorwaarden van de geldverstrekker.`,tags:['verhoging','vergoeding','herfinanciering'],bron:''},
 {id:'hpx-129',thema:'hypotheek-producten',vraag:'Wat vraag je bij de oude geldverstrekker op voordat je een oversluitadvies geeft?',antwoord:`Vraag op:
- een overzicht van alle leningdelen met rente en einddatum rentevast;
- de voorwaarden voor vervroegde aflossing;
- een indicatieve berekening van de vergoeding;
- gegevens over gekoppelde polissen of rekeningen.
Leg deze stukken vast in het dossier.`,tags:['oversluiten','gegevens','dossier'],bron:''},
 {id:'hpx-130',thema:'hypotheek-producten',vraag:'Wat is de rol van de eigenwoningreserve bij oversluiten?',antwoord:`Bij zuiver oversluiten zonder verhuizing speelt de eigenwoningreserve meestal geen rol. Bij verhuizing met oversluiten wel, omdat de reserve de maximale eigenwoningschuld beperkt. Een reserve vervalt na 3 jaar. Leg de berekening vast.`,tags:['eigenwoningreserve','oversluiten','verhuizen'],bron:'Wet IB 2001'},
 {id:'hpx-131',thema:'hypotheek-producten',vraag:'Wat is het verschil tussen een renteaanbod en een bindend aanbod?',antwoord:`Een renteaanbod legt vooral de rente vast en is vaak voorwaardelijk. Een bindend aanbod volgt na beoordeling van de stukken en bevat de definitieve voorwaarden. Pas bij een bindend aanbod is de financiering in principe rond. Informeer de klant over dit verschil.`,tags:['renteaanbod','bindend aanbod','offerte'],bron:''},
 {id:'hpx-132',thema:'hypotheek-producten',vraag:'Wat is het ESIS-formulier?',antwoord:`ESIS staat voor European Standardised Information Sheet. Het is een gestandaardiseerd informatieformulier bij een hypotheekaanbod. Het maakt aanbiedingen vergelijkbaar voor de consument. Het formulier is verplicht op grond van de Europese hypothecair kredietregels.`,tags:['ESIS','informatie','offerte'],bron:'Hypothecair kredietrichtlijn'},
 {id:'hpx-133',thema:'hypotheek-producten',vraag:'Hoe lang heeft een klant bedenktijd na een bindend aanbod?',antwoord:`Op grond van de Europese hypothecair kredietregels geldt een bedenktijd van ten minste 14 dagen. In die periode blijft het aanbod geldig en kan de klant het overwegen. Een klant kan het aanbod wel eerder accepteren. Controleer de voorwaarden van de geldverstrekker.`,tags:['bedenktijd','bindend aanbod','14 dagen'],bron:'Hypothecair kredietrichtlijn'},
 {id:'hpx-134',thema:'hypotheek-producten',vraag:'Waar controleer je een offerte op voordat je die aan de klant voorlegt?',antwoord:`Controleer leenbedrag, rente, rentevaste periode, aflosvorm, looptijd en risicoklasse. Controleer ook bijzondere voorwaarden, zoals verplichte verzekeringen en opschortende voorwaarden. Vergelijk met de aanvraag en het advies. Leg de controle vast.`,tags:['offerte','controle','voorwaarden'],bron:''},
 {id:'hpx-135',thema:'hypotheek-producten',vraag:'Wat zijn opschortende voorwaarden in een offerte?',antwoord:`Opschortende voorwaarden zijn eisen waaraan moet worden voldaan voordat de lening kan worden verstrekt. Denk aan inkomensstukken, een taxatierapport of een getekende koopovereenkomst. Pas daarna kan de lening passeren. Bewaak deze voorwaarden actief.`,tags:['opschortende voorwaarden','offerte','stukken'],bron:''},
 {id:'hpx-136',thema:'hypotheek-producten',vraag:'Wat gebeurt er als de klant na het bindend aanbod het leenbedrag wil verhogen?',antwoord:`Een verhoging leidt meestal tot een nieuwe beoordeling en een gewijzigd aanbod. Daarbij kan een nieuwe rente gelden. Dit kan de planning richting passeren onder druk zetten. Leg de wijziging en de gevolgen vast.`,tags:['offerte','verhoging','wijziging'],bron:''},
 {id:'hpx-137',thema:'hypotheek-producten',vraag:'Kan een offerte worden verlengd?',antwoord:`Bij veel geldverstrekkers kan een offerte worden verlengd, soms tegen kosten of bereidstellingsprovisie. Er kunnen andere voorwaarden of een nieuwe rente gelden. Dat is vooral relevant bij nieuwbouw. Controleer de voorwaarden van de geldverstrekker.`,tags:['offerte','verlenging','bereidstellingsprovisie'],bron:''},
 {id:'hpx-138',thema:'hypotheek-producten',vraag:'Wat zijn de gevolgen van het niet benutten van een getekende offerte?',antwoord:`Als een getekende offerte niet wordt benut, kan de geldverstrekker annuleringskosten rekenen. Dat staat in de offertevoorwaarden. Dit speelt bijvoorbeeld als de klant de woning toch niet koopt. Informeer de klant hierover vooraf.`,tags:['offerte','annulering','kosten'],bron:''},
 {id:'hpx-139',thema:'hypotheek-producten',vraag:'Mag een adviseur meerdere renteaanbiedingen tegelijk aanvragen?',antwoord:`Dat is vaak mogelijk, maar er kunnen kosten verbonden zijn aan het niet benutten van een aanbod. Sommige geldverstrekkers zijn hier strenger in. Doe dit alleen als het in het belang van de klant is. Leg de afweging vast.`,tags:['renteaanbod','meerdere aanbiedingen','kosten'],bron:''},
 {id:'hpx-140',thema:'hypotheek-producten',vraag:'Waarom kan een offerte afwijken van de aanvraag?',antwoord:`De geldverstrekker kan na beoordeling andere voorwaarden stellen. Denk aan een lager leenbedrag, een andere risicoklasse of extra voorwaarden. Ook kan een fout in de aanvraag doorwerken. Controleer elke afwijking en bespreek die met de klant.`,tags:['offerte','afwijking','controle'],bron:''},
 {id:'hpx-141',thema:'hypotheek-producten',vraag:'Wat is een rentekorting voor tijdig accepteren van een offerte?',antwoord:`Sommige geldverstrekkers bieden voordeel als de offerte binnen een korte termijn wordt geaccepteerd. Dat kan de klant onder druk zetten. Wijs de klant op de bedenktijd en de voorwaarden. Leg vast dat de klant hierover is geïnformeerd.`,tags:['offerte','termijn','bedenktijd'],bron:''},
 {id:'hpx-142',thema:'hypotheek-producten',vraag:'Hoe ga je om met een offerte bij nieuwbouw met een lange bouwtijd?',antwoord:`Bij nieuwbouw is de periode tot passeren vaak lang. Een offerte met een langere geldigheidsduur kan nodig zijn. Daarbij kan bereidstellingsprovisie gelden. Controleer de voorwaarden van de geldverstrekker en bewaak de termijn.`,tags:['nieuwbouw','offerte','geldigheidsduur'],bron:''},
 {id:'hpx-143',thema:'hypotheek-producten',vraag:'Wat is een renteaanbod met gegarandeerde rente?',antwoord:`Bij een renteaanbod met gegarandeerde rente staat de rente voor een bepaalde periode vast. Daalt de rente, dan geldt bij veel geldverstrekkers de lagere rente. Stijgt de rente, dan blijft het aanbod gelden. Controleer de voorwaarden van de geldverstrekker.`,tags:['renteaanbod','rentegarantie','offerte'],bron:''},
 {id:'hpx-144',thema:'hypotheek-producten',vraag:'Wat gebeurt er als de passeerdatum na de geldigheidsduur van de offerte valt?',antwoord:`De offerte vervalt dan, tenzij deze tijdig is verlengd. Een nieuwe offerte kan een andere rente en andere voorwaarden hebben. Bewaak de geldigheidsduur actief. Leg de afspraken met notaris en geldverstrekker vast.`,tags:['offerte','geldigheidsduur','passeerdatum'],bron:''},
 {id:'hpx-145',thema:'hypotheek-producten',vraag:'Welke stukken zijn nodig voordat een bindend aanbod kan worden uitgebracht?',antwoord:`Dat verschilt per geldverstrekker. Gebruikelijk zijn inkomensstukken, identiteitsbewijs, koopovereenkomst en taxatierapport. Bij bijzondere situaties zijn extra stukken nodig. Controleer de voorwaarden van de geldverstrekker.`,tags:['bindend aanbod','stukken','acceptatie'],bron:''},
 {id:'hpx-146',thema:'hypotheek-producten',vraag:'Mag de klant een getekende offerte terugtrekken binnen de bedenktijd?',antwoord:`De bedenktijd geeft de klant tijd om het aanbod te overwegen. Na ondertekening is de klant in de regel gebonden aan de voorwaarden van de offerte, inclusief eventuele annuleringskosten. De precieze gevolgen staan in de voorwaarden. Controleer de voorwaarden van de geldverstrekker.`,tags:['offerte','bedenktijd','annulering'],bron:''},
 {id:'hpx-147',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout bij het controleren van de offerte?',antwoord:`Een veelgemaakte fout is het niet controleren van de rentevaste periode en de risicoklasse. Ook worden bijzondere voorwaarden soms over het hoofd gezien. Een andere fout is de offerte niet vergelijken met het advies. Leg de controle vast.`,tags:['offerte','fouten','controle'],bron:''},
 {id:'hpx-148',thema:'hypotheek-producten',vraag:'Hoe leg je de offertefase vast in het dossier?',antwoord:`Leg vast welke aanbiedingen zijn aangevraagd, welke zijn ontvangen en welke is gekozen. Leg ook vast wanneer de klant de offerte heeft ontvangen en getekend. Bewaar de gecontroleerde offerte en de onderbouwing van de keuze. Dit ondersteunt de passendheid van het advies.`,tags:['offerte','vastlegging','dossier'],bron:''},
 {id:'hpx-149',thema:'hypotheek-producten',vraag:'Wat betekent een offerte onder voorbehoud van taxatie?',antwoord:`De offerte is dan afhankelijk van een taxatierapport dat de verwachte waarde bevestigt. Valt de waarde lager uit, dan kan het leenbedrag of de risicoklasse wijzigen. Bespreek dit risico met de klant. Leg de afspraken vast.`,tags:['offerte','taxatie','voorbehoud'],bron:''},
 {id:'hpx-150',thema:'hypotheek-producten',vraag:'Wat doe je als de inkomenssituatie van de klant wijzigt tussen offerte en passeren?',antwoord:`Een wijziging in inkomen of dienstverband kan de acceptatie raken. Meld relevante wijzigingen aan de geldverstrekker, ook als het aanbod al bindend is. Verzwijgen kan als misleiding worden gezien. Leg de melding en de reactie van de geldverstrekker vast.`,tags:['offerte','inkomenswijziging','meldplicht'],bron:''},
 {id:'hpx-151',thema:'hypotheek-producten',vraag:'Binnen welke termijn moet de nieuwe lening worden afgesloten om de verhuisregeling te gebruiken?',antwoord:`De meeste geldverstrekkers stellen een termijn tussen het aflossen van de oude lening en het afsluiten van de nieuwe. Die termijn verschilt per geldverstrekker. Wordt de termijn overschreden, dan vervalt het recht op meenemen. Controleer de voorwaarden van de geldverstrekker en plan de passeerdata daarop.`,tags:['verhuisregeling','termijn','passeren'],bron:''},
 {id:'hpx-152',thema:'hypotheek-producten',vraag:'Garandeert een verhuisregeling dat de klant de nieuwe lening krijgt?',antwoord:`Nee, de verhuisregeling regelt alleen de rente en rentevaste periode. De nieuwe financiering wordt opnieuw beoordeeld volgens de actuele normen en acceptatievoorwaarden. Valt de toets negatief uit, dan helpt de verhuisregeling niet. Bespreek dit vroeg in het traject.`,tags:['verhuisregeling','acceptatie','toetsing'],bron:''},
 {id:'hpx-153',thema:'hypotheek-producten',vraag:'Hoe wordt de rente bepaald als de nieuwe lening hoger is dan de meegenomen lening?',antwoord:`Voor het extra deel geldt meestal de actuele rente van de geldverstrekker. Sommige geldverstrekkers berekenen een gemiddelde rente over het oude en het nieuwe deel. Vergelijk beide varianten met een volledige nieuwe financiering. Controleer de voorwaarden van de geldverstrekker.`,tags:['verhuisregeling','meer lenen','gemiddelde rente'],bron:''},
 {id:'hpx-154',thema:'hypotheek-producten',vraag:'Blijft de resterende rentevaste periode gelijk bij de verhuisregeling?',antwoord:`Bij meenemen loopt de bestaande rentevaste periode in de regel gewoon door. Het extra deel kan een eigen rentevaste periode krijgen. Daardoor kunnen leningdelen op verschillende momenten worden herzien. Leg de einddata per leningdeel vast.`,tags:['verhuisregeling','rentevast','leningdelen'],bron:''},
 {id:'hpx-155',thema:'hypotheek-producten',vraag:'Geldt bij de verhuisregeling een nieuwe risicoklasse?',antwoord:`De risicoklasse wordt meestal opnieuw bepaald op basis van de nieuwe lening en de waarde van de nieuwe woning. Dat kan gunstig of ongunstig uitpakken. Controleer de voorwaarden van de geldverstrekker.`,tags:['verhuisregeling','risicoklasse','LTV'],bron:''},
 {id:'hpx-156',thema:'hypotheek-producten',vraag:'Wanneer is meenemen van de oude rente niet verstandig?',antwoord:`Meenemen is niet verstandig als de oude rente hoger is dan de actuele rente en aflossen bij verkoop boetevrij is. Dan kan een nieuwe financiering tegen de lagere rente voordeliger zijn. Vergelijk ook de voorwaarden van andere geldverstrekkers. Leg de vergelijking vast.`,tags:['verhuisregeling','hogere rente','vergelijking'],bron:''},
 {id:'hpx-157',thema:'hypotheek-producten',vraag:'Hoe werkt de verhuisregeling als de klant eerst koopt en later verkoopt?',antwoord:`Bij kopen voor verkopen loopt de oude lening door op de oude woning. Meenemen is dan vaak pas mogelijk na verkoop, of via een tijdelijke constructie met overbrugging. Sommige geldverstrekkers staan meenemen vooruit toe onder voorwaarden. Controleer de voorwaarden van de geldverstrekker.`,tags:['verhuisregeling','kopen voor verkopen','overbrugging'],bron:''},
 {id:'hpx-158',thema:'hypotheek-producten',vraag:'Wat gebeurt er fiscaal met de aflossingstermijn bij verhuizing met meegenomen lening?',antwoord:`Voor het deel van de nieuwe schuld dat de oude eigenwoningschuld vervangt, loopt de oorspronkelijke aflossingstermijn door. Het extra deel krijgt een nieuwe termijn van 360 maanden. Overgangsrecht kan behouden blijven voor het oude deel. Leg de fiscale historie per deel vast.`,tags:['verhuisregeling','aflossingstermijn','fiscale historie'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-159',thema:'hypotheek-producten',vraag:'Is de verhuisregeling ook van toepassing bij verhuizing met NHG?',antwoord:`De verhuisregeling hangt af van de geldverstrekker. NHG moet voor de nieuwe lening opnieuw worden aangevraagd. De nieuwe lening moet passen binnen de NHG-voorwaarden. Controleer de voorwaarden van NHG en de geldverstrekker.`,tags:['verhuisregeling','NHG','voorwaarden'],bron:'NHG'},
 {id:'hpx-160',thema:'hypotheek-producten',vraag:'Waarom ontstaat er soms geen eigenwoningreserve terwijl de woning met winst is verkocht?',antwoord:`Een eigenwoningreserve ontstaat alleen als de verkoopopbrengst na kosten hoger is dan de eigenwoningschuld. Een aflossingsvrije of hoge schuld kan de winst geheel opslokken. Ook een deel box 3-schuld op de woning telt anders mee. Maak de berekening altijd op basis van de werkelijke eigenwoningschuld.`,tags:['eigenwoningreserve','verkoop','berekening'],bron:'Wet IB 2001'},
 {id:'hpx-161',thema:'hypotheek-producten',vraag:'Wat is een rekenvoorbeeld van de eigenwoningreserve?',antwoord:`Stel: verkoopprijs 400.000 euro, verkoopkosten 10.000 euro en eigenwoningschuld 250.000 euro. De eigenwoningreserve is 140.000 euro. Bij aankoop van een woning van 500.000 euro is de maximale eigenwoningschuld 360.000 euro, exclusief kosten. Illustratief.`,tags:['eigenwoningreserve','rekenvoorbeeld','verhuizen'],bron:'Wet IB 2001'},
 {id:'hpx-162',thema:'hypotheek-producten',vraag:'Welke verkoopkosten tellen mee bij de eigenwoningreserve?',antwoord:`Kosten die direct verband houden met de verkoop tellen mee. Denk aan makelaarskosten en kosten voor het aanprijzen van de woning. Kosten voor de aankoop van de nieuwe woning tellen niet mee. Controleer het actuele standpunt van de Belastingdienst.`,tags:['eigenwoningreserve','verkoopkosten','definitie'],bron:'Belastingdienst'},
 {id:'hpx-163',thema:'hypotheek-producten',vraag:'Kan een klant de eigenwoningreserve vermijden door de overwaarde eerst te sparen?',antwoord:`Nee, de eigenwoningreserve geldt ongeacht wat de klant met de overwaarde doet. Ook als het geld op een spaarrekening blijft staan, beperkt de reserve de maximale eigenwoningschuld op de nieuwe woning. Wat niet in de woning wordt gestoken, leidt tot een box 3-deel. Leg dit vast in het advies.`,tags:['eigenwoningreserve','overwaarde','box 3'],bron:'Wet IB 2001'},
 {id:'hpx-164',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout bij de verhuisregeling?',antwoord:`Een veelgemaakte fout is de termijn voor meenemen niet bewaken. Een andere fout is de oude rente meenemen terwijl een nieuwe financiering gunstiger is. Ook wordt de eigenwoningreserve soms vergeten. Leg elke stap en berekening vast.`,tags:['verhuisregeling','fouten','termijn'],bron:''},
 {id:'hpx-165',thema:'hypotheek-producten',vraag:'Mag een klant bij verhuizing een deel van de oude lening meenemen en de rest aflossen?',antwoord:`Dat is meestal mogelijk. Het niet meegenomen deel wordt afgelost uit de verkoopopbrengst. Bij verkoop is aflossen vaak boetevrij. Controleer de voorwaarden van de geldverstrekker.`,tags:['verhuisregeling','gedeeltelijk','aflossen'],bron:''},
 {id:'hpx-166',thema:'hypotheek-producten',vraag:'Hoe ga je om met een woning die verhuurd wordt na verhuizing?',antwoord:`Een verhuurde woning is geen eigen woning meer. De lening op die woning is dan geen eigenwoningschuld. Er kan ook toestemming van de geldverstrekker nodig zijn om te verhuren. Controleer de voorwaarden van de geldverstrekker en de fiscale gevolgen.`,tags:['verhuur','eigen woning','toestemming'],bron:''},
 {id:'hpx-167',thema:'hypotheek-producten',vraag:'Wat gebeurt er met de lening op de oude woning als die na drie jaar nog niet verkocht is?',antwoord:`Na de termijn van 3 jaar geldt de oude woning fiscaal niet meer als eigen woning. De lening op die woning gaat dan in de regel naar box 3. Dat verhoogt de netto lasten. Bespreek vooraf een plan voor het geval de verkoop lang duurt.`,tags:['oude woning','3 jaar','box 3'],bron:'Wet IB 2001'},
 {id:'hpx-168',thema:'hypotheek-producten',vraag:'Wat gebeurt er als de oude woning tijdelijk wordt verhuurd terwijl die te koop staat?',antwoord:`Bij verhuur geldt de woning niet meer als leegstaande, te koop staande eigen woning. De renteaftrek kan dan vervallen. Bij tijdelijke verhuur gelden specifieke regels. Controleer het actuele standpunt van de Belastingdienst.`,tags:['oude woning','tijdelijke verhuur','renteaftrek'],bron:'Belastingdienst'},
 {id:'hpx-169',thema:'hypotheek-producten',vraag:'Wat betekent een verkoop onder voorbehoud voor de hoogte van de overbrugging?',antwoord:`Zolang ontbindende voorwaarden lopen, is de verkoop niet definitief. Veel geldverstrekkers rekenen dan met een lager percentage of behandelen het als open overbrugging. Na het verstrijken van de voorwaarden kan de overbrugging vaak worden vastgezet. Controleer de voorwaarden van de geldverstrekker.`,tags:['overbrugging','voorbehoud','ontbindende voorwaarden'],bron:''},
 {id:'hpx-170',thema:'hypotheek-producten',vraag:'Wat is het verschil tussen een vaste en een open overbrugging?',antwoord:`Bij een vaste overbrugging is de oude woning al definitief verkocht en zijn de ontbindende voorwaarden verstreken. Bij een open overbrugging is de oude woning nog niet verkocht. Een open overbrugging is risicovoller. Geldverstrekkers stellen daarvoor strengere eisen.`,tags:['overbrugging','vast','open'],bron:''},
 {id:'hpx-171',thema:'hypotheek-producten',vraag:'Hoe lang mag een overbruggingskrediet lopen?',antwoord:`Geldverstrekkers stellen een maximale looptijd, vaak uitgedrukt in maanden. Fiscaal geldt voor een overbruggingslening een maximale termijn van 3 jaar zonder aflossingseis. Controleer de voorwaarden van de geldverstrekker.`,tags:['overbrugging','looptijd','3 jaar'],bron:'Wet IB 2001'},
 {id:'hpx-172',thema:'hypotheek-producten',vraag:'Geldt de aflossingseis voor een overbruggingslening?',antwoord:`Nee, voor een overbruggingslening voor de aankoop van een nieuwe eigen woning geldt de aflossingseis niet, mits aan de voorwaarden wordt voldaan. De lening mag dan aflossingsvrij zijn. De maximale termijn is 3 jaar. Controleer het actuele standpunt van de Belastingdienst.`,tags:['overbrugging','aflossingseis','fiscaal'],bron:'Wet IB 2001'},
 {id:'hpx-173',thema:'hypotheek-producten',vraag:'Wat gebeurt er als de koper van de oude woning afhaakt tijdens de overbrugging?',antwoord:`Dan blijft de klant zitten met dubbele lasten en een openstaand overbruggingskrediet. De geldverstrekker kan aanvullende eisen stellen. Bij een open overbrugging is dit risico groter. Bespreek dit scenario vooraf en leg het vast.`,tags:['overbrugging','koper haakt af','risico'],bron:''},
 {id:'hpx-174',thema:'hypotheek-producten',vraag:'Wat als de verkoopprijs lager uitvalt dan verwacht?',antwoord:`Dan is de overwaarde lager dan waarmee het overbruggingskrediet is berekend. Het verschil moet worden afgelost uit eigen middelen of via een aanvullende financiering. Dat kan fiscale gevolgen hebben. Bespreek dit scenario vooraf.`,tags:['overbrugging','lagere verkoopprijs','tekort'],bron:''},
 {id:'hpx-175',thema:'hypotheek-producten',vraag:'Hoe wordt de rente van een overbruggingskrediet gerekend?',antwoord:`Bij een overbruggingskrediet geldt vaak een variabele rente. Het krediet wordt meestal niet tussentijds afgelost. De rente wordt maandelijks betaald. Controleer de voorwaarden van de geldverstrekker.`,tags:['overbrugging','rente','variabel'],bron:''},
 {id:'hpx-176',thema:'hypotheek-producten',vraag:'Kan een overbruggingskrediet worden afgesloten bij een andere geldverstrekker dan de nieuwe hypotheek?',antwoord:`In de praktijk verstrekt meestal de geldverstrekker van de nieuwe hypotheek ook het overbruggingskrediet. Een andere constructie is soms mogelijk, maar complexer. Controleer de voorwaarden van de geldverstrekker.`,tags:['overbrugging','geldverstrekker','constructie'],bron:''},
 {id:'hpx-177',thema:'hypotheek-producten',vraag:'Wat leg je vast bij een overbruggingsadvies?',antwoord:`Leg vast:
- de berekening van de overwaarde;
- de status van de verkoop;
- de dubbele lasten en de periode;
- de scenarios bij lagere opbrengst of uitstel.
Leg ook vast welke buffer de klant heeft.`,tags:['overbrugging','vastlegging','scenarios'],bron:''},
 {id:'hpx-178',thema:'hypotheek-producten',vraag:'Hoe ga je om met een overbrugging bij nieuwbouw?',antwoord:`Bij nieuwbouw is de bouwtijd onzeker en kan de overbrugging langer duren. De klant betaalt dan langer dubbele lasten. Plan de verkoop van de oude woning zorgvuldig. Controleer de voorwaarden van de geldverstrekker.`,tags:['overbrugging','nieuwbouw','bouwtijd'],bron:''},
 {id:'hpx-179',thema:'hypotheek-producten',vraag:'Wat is het verband tussen overbrugging en de eigenwoningreserve?',antwoord:`De overwaarde van de oude woning vormt de eigenwoningreserve. Die moet in de nieuwe woning worden ingebracht. Het overbruggingskrediet wordt na verkoop afgelost uit die overwaarde. De reserve beperkt de maximale eigenwoningschuld op de nieuwe woning.`,tags:['overbrugging','eigenwoningreserve','overwaarde'],bron:'Wet IB 2001'},
 {id:'hpx-180',thema:'hypotheek-producten',vraag:'Welke kosten zijn verbonden aan een overbruggingskrediet?',antwoord:`Naast rente kunnen er afsluitkosten en notariskosten zijn. Ook kan een taxatie van de oude woning nodig zijn. De kosten verschillen per geldverstrekker. Neem alle kosten op in de financieringsopzet.`,tags:['overbrugging','kosten','financieringsopzet'],bron:''},
 {id:'hpx-181',thema:'hypotheek-producten',vraag:'Wat zijn alternatieven voor een overbruggingskrediet?',antwoord:`Alternatieven zijn wachten met kopen tot de oude woning is verkocht, eigen middelen inzetten of een tijdelijke lening van familie. Ook een tijdelijke verhoging bij de huidige geldverstrekker kan soms. Elk alternatief heeft eigen risicos. Leg de afweging vast.`,tags:['overbrugging','alternatieven','afweging'],bron:''},
 {id:'hpx-182',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout bij overbrugging?',antwoord:`Een veelgemaakte fout is te optimistisch rekenen met de verkoopprijs. Ook wordt de duur van de dubbele lasten onderschat. Een andere fout is de eigenwoningreserve niet goed verwerken. Leg alle aannames vast.`,tags:['overbrugging','fouten','aannames'],bron:''},
 {id:'hpx-183',thema:'hypotheek-producten',vraag:'Kan een overbruggingskrediet worden verlengd?',antwoord:`Bij sommige geldverstrekkers kan een overbruggingskrediet worden verlengd. Daarvoor gelden voorwaarden, zoals een actuele taxatie of verkoopinspanning. Fiscaal geldt de maximale termijn van 3 jaar. Controleer de voorwaarden van de geldverstrekker.`,tags:['overbrugging','verlenging','voorwaarden'],bron:''},
 {id:'hpx-184',thema:'hypotheek-producten',vraag:'Hoe ga je om met een klant die verkoopt aan een familielid tijdens de overbrugging?',antwoord:`Een verkoop aan familie moet zakelijk zijn en tegen marktwaarde plaatsvinden. Anders kunnen er schenkings- of fiscale gevolgen zijn. Een taxatie kan de marktwaarde onderbouwen. Leg de afspraken vast.`,tags:['overbrugging','familie','marktwaarde'],bron:''},
 {id:'hpx-185',thema:'hypotheek-producten',vraag:'Wie bepaalt of een gemeente startersleningen aanbiedt?',antwoord:`De gemeente bepaalt zelf of zij startersleningen aanbiedt en onder welke voorwaarden. Denk aan doelgroep, maximale koopsom en maximale lening. De uitvoering ligt meestal bij SVn. Controleer de actuele voorwaarden bij de gemeente en SVn.`,tags:['starterslening','gemeente','SVn'],bron:'SVn'},
 {id:'hpx-186',thema:'hypotheek-producten',vraag:'Hoe verloopt de aanvraag van een starterslening?',antwoord:`De klant vraagt eerst een toewijzing aan bij de gemeente. Daarna toetst SVn de aanvraag. De hypotheek bij de geldverstrekker en de starterslening worden samen beoordeeld. Plan de aanvraag tijdig in.`,tags:['starterslening','aanvraag','toewijzing'],bron:'SVn'},
 {id:'hpx-187',thema:'hypotheek-producten',vraag:'Hoe wordt de starterslening na de eerste jaren opnieuw getoetst?',antwoord:`Na een aantal jaren wordt beoordeeld of de klant de volledige maandlast kan betalen. Kan dat niet, dan kan een lagere maandlast gelden. Dit wordt periodiek opnieuw beoordeeld. Controleer de actuele voorwaarden van SVn.`,tags:['starterslening','hertoetsing','maandlast'],bron:'SVn'},
 {id:'hpx-188',thema:'hypotheek-producten',vraag:'Mag een starterslening tussentijds worden afgelost?',antwoord:`Een starterslening kan in de regel tussentijds worden afgelost. Controleer de voorwaarden van SVn op eventuele kosten. Vraag een actuele aflosnota op. Leg de afspraken vast.`,tags:['starterslening','aflossen','SVn'],bron:'SVn'},
 {id:'hpx-189',thema:'hypotheek-producten',vraag:'Wat gebeurt er met de starterslening bij verkoop van de woning?',antwoord:`Bij verkoop moet de starterslening worden afgelost uit de verkoopopbrengst. Dat geldt ook als er weinig overwaarde is. Bij onvoldoende opbrengst kan een restschuld ontstaan. Controleer de voorwaarden van SVn.`,tags:['starterslening','verkoop','aflossen'],bron:'SVn'},
 {id:'hpx-190',thema:'hypotheek-producten',vraag:'Is NHG een voorwaarde voor een starterslening?',antwoord:`Bij veel gemeentelijke regelingen is NHG een voorwaarde voor de totale financiering. Dat betekent dat de koopsom en de totale lening binnen de NHG-grenzen moeten blijven. Controleer de actuele voorwaarden bij de gemeente, SVn en NHG.`,tags:['starterslening','NHG','voorwaarden'],bron:'SVn'},
 {id:'hpx-191',thema:'hypotheek-producten',vraag:'Hoe wordt de starterslening gezekerd?',antwoord:`De starterslening wordt meestal gezekerd met een hypotheekrecht op de woning. Dat staat meestal achter de hypotheek van de geldverstrekker. Dit betekent dat SVn pas na de geldverstrekker wordt terugbetaald. Controleer de voorwaarden van SVn.`,tags:['starterslening','zekerheid','hypotheekrecht'],bron:'SVn'},
 {id:'hpx-192',thema:'hypotheek-producten',vraag:'Wat is de rol van de adviseur bij een starterslening?',antwoord:`De adviseur beoordeelt of de starterslening past bij de klant. Hij informeert over de voorwaarden en de hertoetsing. Ook coördineert hij de aanvragen bij gemeente, SVn en geldverstrekker. Leg het advies en de afspraken vast.`,tags:['starterslening','adviseur','coördinatie'],bron:'SVn'},
 {id:'hpx-193',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout bij de starterslening?',antwoord:`Een veelgemaakte fout is de termijnen van gemeente en SVn niet goed plannen. Daardoor kan de passeerdatum in gevaar komen. Ook worden de voorwaarden bij latere hertoetsing soms niet besproken. Leg alle stappen vast.`,tags:['starterslening','fouten','planning'],bron:'SVn'},
 {id:'hpx-194',thema:'hypotheek-producten',vraag:'Kan een starterslening worden gecombineerd met een familielening?',antwoord:`Dat is niet uitgesloten, maar de totale financiering moet passen binnen de voorwaarden van gemeente, SVn en geldverstrekker. Een familielening telt mee in de toetsing. Controleer de voorwaarden. Leg de afweging vast.`,tags:['starterslening','familielening','toetsing'],bron:'SVn'},
 {id:'hpx-195',thema:'hypotheek-producten',vraag:'Waarom wordt bij een starterslening de toekomstige maandlast extra besproken?',antwoord:`Na de eerste jaren kan de maandlast stijgen als rente en aflossing gaan lopen. De klant moet daarop voorbereid zijn. Laat de verwachte maandlast zien na de betalingsvrije periode. Leg dit vast.`,tags:['starterslening','maandlast','toekomst'],bron:'SVn'},
 {id:'hpx-196',thema:'hypotheek-producten',vraag:'Hoe ga je om met een starterslening bij een verhuizing?',antwoord:`Bij verhuizing wordt de starterslening in de regel afgelost uit de verkoopopbrengst. Meenemen naar een nieuwe woning is niet gebruikelijk. Controleer de voorwaarden van SVn. Leg de afspraken vast.`,tags:['starterslening','verhuizen','aflossen'],bron:'SVn'},
 {id:'hpx-197',thema:'hypotheek-producten',vraag:'Welke informatie leg je vast bij een starterslening in het dossier?',antwoord:`Leg vast:
- de toewijzing van de gemeente;
- de beoordeling door SVn;
- de voorwaarden en de hertoetsing;
- de besproken maandlast na de betalingsvrije periode.
Bewaar alle correspondentie.`,tags:['starterslening','vastlegging','dossier'],bron:'SVn'},
 {id:'hpx-198',thema:'hypotheek-producten',vraag:'Mag een starterslening worden gebruikt voor een verbouwing?',antwoord:`De starterslening is bedoeld voor de aankoop van een woning door een starter. Of verbouwingskosten mogen meetellen, hangt af van de gemeentelijke regeling. Controleer de voorwaarden van de gemeente en SVn.`,tags:['starterslening','verbouwing','voorwaarden'],bron:'SVn'},
 {id:'hpx-199',thema:'hypotheek-producten',vraag:'Hoe wordt de hoogte van een starterslening in hoofdlijnen bepaald?',antwoord:`De starterslening overbrugt het verschil tussen de totale verwervingskosten en de hypotheek die de klant op basis van inkomen kan krijgen. Het bedrag is begrensd door het maximum van de gemeentelijke regeling. SVn rekent dit na in de eigen toets. Controleer de actuele voorwaarden bij de gemeente en SVn.`,tags:['starterslening','hoogte','verwervingskosten'],bron:'SVn'},
 {id:'hpx-200',thema:'hypotheek-producten',vraag:'Wat betekent een inkomensstijging voor de starterslening bij de hertoetsing?',antwoord:`Bij de periodieke hertoetsing kijkt SVn naar het actuele inkomen. Een hoger inkomen leidt in de regel tot een hogere maandlast voor de starterslening, tot de volledige annuïteit. Dat is de bedoeling van de regeling. Bespreek dit vooraf met de klant en controleer de voorwaarden van SVn.`,tags:['starterslening','hertoetsing','inkomen'],bron:'SVn'},
 {id:'hpx-201',thema:'hypotheek-producten',vraag:'Wat moet minimaal in een leenovereenkomst voor een familiehypotheek staan?',antwoord:`Leg minimaal vast:
- de namen van lener en geldgever;
- het leenbedrag en het doel;
- de rente en de rentevaste periode;
- de looptijd en het aflosschema van maximaal 360 maanden.
Een onderhandse overeenkomst is mogelijk, een notariële akte geeft extra zekerheid.`,tags:['familiehypotheek','leenovereenkomst','vastlegging'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-202',thema:'hypotheek-producten',vraag:'Hoe bepaal je een zakelijke rente bij een familiehypotheek?',antwoord:`Een zakelijke rente is de rente die een bank zou vragen voor een vergelijkbare lening. Kijk naar dezelfde rentevaste periode, looptijd en zekerheid. Zonder hypotheekrecht is een hogere rente vaak zakelijk dan met. Leg de vergelijking met actuele bankrentes vast in het dossier.`,tags:['familiehypotheek','zakelijke rente','onderbouwing'],bron:'Belastingdienst'},
 {id:'hpx-203',thema:'hypotheek-producten',vraag:'Wat gebeurt er als de rente van een familiehypotheek hoger is dan zakelijk?',antwoord:`Het deel van de rente boven het zakelijke niveau is in de regel niet aftrekbaar. Dat meerdere kan worden gezien als een schenking van het kind aan de ouder. Dit levert dus geen fiscaal voordeel op. Onderbouw de rente met een vergelijking.`,tags:['familiehypotheek','te hoge rente','renteaftrek'],bron:'Belastingdienst'},
 {id:'hpx-204',thema:'hypotheek-producten',vraag:'Wat gebeurt er als de rente van een familiehypotheek lager is dan zakelijk?',antwoord:`Een lagere rente is toegestaan, maar het rentevoordeel kan als schenking van de ouder worden gezien. Bij een renteloze lening kan sprake zijn van een jaarlijkse schenking. Afhankelijk van de vrijstellingen kan schenkbelasting verschuldigd zijn. Controleer de actuele vrijstellingen bij de Belastingdienst.`,tags:['familiehypotheek','lage rente','schenking'],bron:'Belastingdienst'},
 {id:'hpx-205',thema:'hypotheek-producten',vraag:'Moet de rente van een familiehypotheek daadwerkelijk worden betaald?',antwoord:`Ja, alleen daadwerkelijk betaalde rente is aftrekbaar. Betaal de rente aantoonbaar via de bank. Rente die wordt kwijtgescholden is niet betaald. Bewaar de betaalbewijzen in het dossier.`,tags:['familiehypotheek','betaling','bewijs'],bron:'Belastingdienst'},
 {id:'hpx-206',thema:'hypotheek-producten',vraag:'Mogen ouders de ontvangen rente terugschenken aan het kind?',antwoord:`Ouders mogen een schenking doen, ook nadat zij rente hebben ontvangen. Bij een vooraf afgesproken terugschenking kan de Belastingdienst de constructie als niet zakelijk aanmerken. Het risico is dat de renteaftrek wordt betwist. Laat bij twijfel een fiscalist meekijken.`,tags:['familiehypotheek','terugschenken','risico'],bron:'Belastingdienst'},
 {id:'hpx-207',thema:'hypotheek-producten',vraag:'Welke gegevens moet de lener doorgeven aan de Belastingdienst bij een familiehypotheek?',antwoord:`Bij een lening van een particulier geldt een informatieplicht. De lener geeft in de aangifte onder meer gegevens van de geldgever en de lening door. Zonder deze gegevens kan de renteaftrek vervallen. Wijs de klant hierop en leg dit vast.`,tags:['familiehypotheek','informatieplicht','aangifte'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-208',thema:'hypotheek-producten',vraag:'Hoe telt een familiehypotheek fiscaal mee bij de ouders?',antwoord:`Voor de ouders is de lening een vordering. Die vordering valt in box 3. De fiscale gevolgen hangen af van de actuele box 3-regels. Laat de ouders hun eigen fiscale situatie controleren.`,tags:['familiehypotheek','box 3','vordering'],bron:'Belastingdienst'},
 {id:'hpx-209',thema:'hypotheek-producten',vraag:'Wat gebeurt er met een familiehypotheek bij overlijden van de ouder?',antwoord:`Bij overlijden valt de vordering in de nalatenschap. Erfgenamen worden dan schuldeiser van het kind. Dat kan spanningen geven tussen broers en zussen. Bespreek met de ouders of een testament nodig is.`,tags:['familiehypotheek','overlijden','nalatenschap'],bron:''},
 {id:'hpx-210',thema:'hypotheek-producten',vraag:'Kan een familiehypotheek worden kwijtgescholden?',antwoord:`Ouders kunnen een deel van de lening kwijtschelden. Dat is een schenking aan het kind. Afhankelijk van de vrijstellingen kan schenkbelasting verschuldigd zijn. De kwijtschelding verlaagt de eigenwoningschuld.`,tags:['familiehypotheek','kwijtschelding','schenking'],bron:'Belastingdienst'},
 {id:'hpx-211',thema:'hypotheek-producten',vraag:'Wat is de rangorde tussen een bankhypotheek en een familiehypotheek?',antwoord:`De bank eist meestal de eerste rang. Een familiehypotheek met hypotheekrecht staat dan in tweede rang. Sommige geldverstrekkers vragen een achterstellingsverklaring. Controleer de voorwaarden van de geldverstrekker.`,tags:['familiehypotheek','rangorde','achterstelling'],bron:''},
 {id:'hpx-212',thema:'hypotheek-producten',vraag:'Hoe ga je om met verschillen tussen kinderen bij een familiehypotheek?',antwoord:`Een lening aan één kind kan voelen als bevoordeling ten opzichte van andere kinderen. Ouders kunnen dit bespreken en vastleggen. Een testament kan helpen bij gelijke behandeling. Verwijs de ouders zo nodig naar een notaris.`,tags:['familiehypotheek','gelijke behandeling','testament'],bron:''},
 {id:'hpx-213',thema:'hypotheek-producten',vraag:'Wat is een risico voor ouders bij een familiehypotheek?',antwoord:`Ouders lopen het risico dat het kind niet kan betalen. Ook hebben zij het geld niet meer vrij beschikbaar. Dat kan een probleem zijn bij zorgkosten. Bespreek de liquiditeit van de ouders.`,tags:['familiehypotheek','risico ouders','liquiditeit'],bron:''},
 {id:'hpx-214',thema:'hypotheek-producten',vraag:'Mag een familiehypotheek aflossingsvrij zijn?',antwoord:`Een aflossingsvrije familiehypotheek voldoet niet aan de aflossingseis. De rente is dan in de regel niet aftrekbaar en de lening valt in box 3. Voor renteaftrek is minimaal annuïtaire aflossing nodig. Leg de keuze vast.`,tags:['familiehypotheek','aflossingsvrij','box 3'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-215',thema:'hypotheek-producten',vraag:'Kan een familiehypotheek worden gebruikt voor een verbouwing?',antwoord:`Ja, als de lening wordt gebruikt voor verbetering of onderhoud van de eigen woning. De lening moet dan voldoen aan de aflossingseis en de informatieplicht. Bewaar facturen. Leg het doel van de lening vast.`,tags:['familiehypotheek','verbouwing','eigenwoningschuld'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'hpx-216',thema:'hypotheek-producten',vraag:'Mag een familiehypotheek ook van een broer of vriend komen?',antwoord:`Ja, de regels voor een lening van een particulier gelden ook bij broers, zussen of vrienden. De lening moet zakelijk zijn en voldoen aan de aflossingseis. Ook de informatieplicht geldt. Leg de afspraken vast.`,tags:['familiehypotheek','particulier','zakelijk'],bron:'Wet IB 2001'},
 {id:'hpx-217',thema:'hypotheek-producten',vraag:'Wat leg je vast in het dossier bij een familiehypotheek?',antwoord:`Leg vast:
- de leenovereenkomst;
- de onderbouwing van de zakelijke rente;
- de afspraak over aflossing;
- het advies over de rol van de bankhypotheek.
Bewaar ook de betaalbewijzen.`,tags:['familiehypotheek','vastlegging','dossier'],bron:''},
 {id:'hpx-218',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout bij een familiehypotheek?',antwoord:`Een veelgemaakte fout is geen aflosschema vastleggen. Ook wordt de rente soms niet aantoonbaar betaald. Een andere fout is de informatieplicht vergeten. Leg alle stappen vast.`,tags:['familiehypotheek','fouten','aflosschema'],bron:''},
 {id:'hpx-219',thema:'hypotheek-producten',vraag:'Wat als ouders willen schenken en lenen tegelijk?',antwoord:`Een combinatie van schenken en lenen is mogelijk. Schenk bijvoorbeeld jaarlijks een deel van de rente of aflossing via een aparte schenking. Houd schenking en lening administratief gescheiden. Controleer de actuele vrijstellingen bij de Belastingdienst.`,tags:['familiehypotheek','schenken','combinatie'],bron:'Belastingdienst'},
 {id:'hpx-220',thema:'hypotheek-producten',vraag:'Mag de rente van een familiehypotheek gedurende de looptijd worden aangepast?',antwoord:`Dat kan als dat in de overeenkomst is afgesproken. De nieuwe rente moet zakelijk zijn op het moment van aanpassing. Leg de aanpassing schriftelijk vast. Onderbouw de rente opnieuw.`,tags:['familiehypotheek','renteaanpassing','zakelijk'],bron:''},
 {id:'hpx-221',thema:'hypotheek-producten',vraag:'Hoe ga je om met een familiehypotheek bij scheiding?',antwoord:`Bij scheiding blijft de lening bestaan, tenzij anders wordt afgesproken. De ouders blijven schuldeiser. Het kind en de ex-partner moeten afspreken wie de lening overneemt. Leg de afspraken vast.`,tags:['familiehypotheek','scheiding','overname'],bron:''},
 {id:'hpx-222',thema:'hypotheek-producten',vraag:'Is een notariële akte verplicht voor een familiehypotheek?',antwoord:`Een notariële akte is niet verplicht voor de renteaftrek. Een schriftelijke overeenkomst is voldoende. Een notariële hypotheekakte geeft de ouders wel zekerheid. Weeg de kosten af tegen die zekerheid.`,tags:['familiehypotheek','notariële akte','zekerheid'],bron:''},
 {id:'hpx-223',thema:'hypotheek-producten',vraag:'Wat is een vervanging van een bankhypotheek door een familiehypotheek?',antwoord:`Ouders kunnen een bestaande bankhypotheek overnemen door een lening te verstrekken. Daarbij gelden dezelfde fiscale regels. Bij aflossing van de bankhypotheek kan een vergoeding gelden. Leg de afweging vast.`,tags:['familiehypotheek','oversluiten','bankhypotheek'],bron:''},
 {id:'hpx-224',thema:'hypotheek-producten',vraag:'Wat is een rekenvoorbeeld van een familiehypotheek?',antwoord:`Stel: ouders lenen 100.000 euro tegen 4 procent over 30 jaar annuïtair. De maandlast is ongeveer 477 euro bruto. In het eerste jaar is de rente ongeveer 3.970 euro. Illustratief, zonder rekening te houden met actuele tarieven.`,tags:['familiehypotheek','rekenvoorbeeld','maandlast'],bron:''},
 {id:'hpx-225',thema:'hypotheek-producten',vraag:'Waarvoor wordt een gemeentelijke verzilverlening in de praktijk gebruikt?',antwoord:`Een gemeentelijke verzilverlening is bedoeld voor oudere huiseigenaren met overwaarde en weinig ruimte in het inkomen. De lening wordt vooral gebruikt voor woningaanpassing, levensloopbestendig maken of verduurzaming. De gemeente bepaalt de doelen en voorwaarden. De rente wordt meestal bijgeschreven. Aflossing volgt bij verkoop of overlijden.`,tags:['verzilverlening','ouderen','overwaarde'],bron:'SVn'},
 {id:'hpx-226',thema:'hypotheek-producten',vraag:'Hoe werkt renteopbouw bij een verzilverlening?',antwoord:`Bij renteopbouw wordt de rente niet maandelijks betaald, maar bij de lening opgeteld. Daardoor groeit de schuld. Er ontstaat rente op rente. Laat zien hoe de schuld groeit over de jaren.`,tags:['renteopbouw','verzilverlening','rente op rente'],bron:''},
 {id:'hpx-227',thema:'hypotheek-producten',vraag:'Wat is een rekenvoorbeeld van renteopbouw?',antwoord:`Stel: lening 50.000 euro tegen 5 procent rente met renteopbouw. Na ongeveer 14 jaar is de schuld verdubbeld tot ongeveer 100.000 euro. Dat komt door rente op rente. Illustratief, zonder actuele tarieven.`,tags:['renteopbouw','rekenvoorbeeld','rente op rente'],bron:''},
 {id:'hpx-228',thema:'hypotheek-producten',vraag:'Is de rente op een verzilverlening fiscaal aftrekbaar?',antwoord:`Een lening zonder aflossing voldoet niet aan de aflossingseis. De rente is dan in de regel niet aftrekbaar. De lening valt dan meestal in box 3. Controleer het actuele standpunt van de Belastingdienst.`,tags:['verzilverlening','renteaftrek','box 3'],bron:'Belastingdienst'},
 {id:'hpx-229',thema:'hypotheek-producten',vraag:'Wat is een seniorenhypotheek?',antwoord:`Een seniorenhypotheek is een hypotheek voor oudere huiseigenaren. Vaak wordt de toetsing aangepast aan pensioen en vermogen. Er zijn varianten met aflossingsvrije delen. Controleer de voorwaarden van de geldverstrekker.`,tags:['seniorenhypotheek','ouderen','toetsing'],bron:''},
 {id:'hpx-230',thema:'hypotheek-producten',vraag:'Wat is een lijfrentehypotheek?',antwoord:`Bij een lijfrentehypotheek wordt de lening gebruikt voor een periodieke uitkering. De klant zet overwaarde om in inkomen. De voorwaarden en fiscale gevolgen zijn complex. Controleer de voorwaarden van de aanbieder.`,tags:['lijfrentehypotheek','periodieke uitkering','overwaarde'],bron:''},
 {id:'hpx-231',thema:'hypotheek-producten',vraag:'Wat zijn de risicos van verzilveren voor erfgenamen?',antwoord:`Door renteopbouw kan de overwaarde fors dalen. Erfgenamen erven dan minder. Bij overlijden moet de lening vaak binnen een termijn worden afgelost. Bespreek dit met de klant en eventueel de erfgenamen.`,tags:['verzilveren','erfgenamen','nalatenschap'],bron:''},
 {id:'hpx-232',thema:'hypotheek-producten',vraag:'Moet je erfgenamen betrekken bij een verzilveradvies?',antwoord:`Het is niet verplicht, maar wel verstandig. Erfgenamen worden geraakt door de lening. Betrek ze als de klant dat wil. Leg vast wie bij het gesprek aanwezig was.`,tags:['verzilveren','erfgenamen','gesprek'],bron:''},
 {id:'hpx-233',thema:'hypotheek-producten',vraag:'Wat gebeurt er als de klant naar een zorginstelling verhuist?',antwoord:`Bij verhuizing naar een zorginstelling kan de lening opeisbaar worden. De woning moet dan vaak worden verkocht. Er gelden vaak termijnen. Controleer de voorwaarden van de aanbieder.`,tags:['verzilveren','zorginstelling','opeisbaar'],bron:''},
 {id:'hpx-234',thema:'hypotheek-producten',vraag:'Wat is een geen-restschuldgarantie?',antwoord:`Bij sommige verzilverproducten hoeven erfgenamen geen restschuld te betalen als de lening hoger is dan de waarde. De aanbieder neemt het verlies dan voor zijn rekening. Niet elk product heeft deze garantie. Controleer de voorwaarden van de aanbieder.`,tags:['restschuld','garantie','verzilveren'],bron:''},
 {id:'hpx-235',thema:'hypotheek-producten',vraag:'Hoe wordt de maximale verzilverlening bepaald?',antwoord:`De maximale lening hangt vaak af van de leeftijd van de klant en de woningwaarde. Hoe ouder de klant, hoe hoger het percentage. Dit verschilt per aanbieder. Controleer de voorwaarden van de aanbieder.`,tags:['verzilverlening','maximum','leeftijd'],bron:''},
 {id:'hpx-236',thema:'hypotheek-producten',vraag:'Wat is de invloed van verzilveren op toeslagen en zorgkosten?',antwoord:`Een uitkering uit verzilveren kan vermogen of inkomen verhogen. Dat kan invloed hebben op toeslagen en eigen bijdragen voor zorg. Bespreek dit met de klant. Laat bij twijfel een specialist meekijken.`,tags:['verzilveren','toeslagen','zorgkosten'],bron:''},
 {id:'hpx-237',thema:'hypotheek-producten',vraag:'Wat is het effect van verzilveren op de Wet Hillen?',antwoord:`Een verzilverlening die geen eigenwoningschuld is, verandert niets aan het eigenwoningforfait. Bij geen of een lage eigenwoningschuld kan de Wet Hillen-aftrek gelden. Die wordt vanaf 2019 in 30 jaar afgebouwd. Controleer het actuele standpunt van de Belastingdienst.`,tags:['Wet Hillen','verzilveren','eigenwoningforfait'],bron:'Wet IB 2001'},
 {id:'hpx-238',thema:'hypotheek-producten',vraag:'Wat leg je vast in het dossier bij verzilveren?',antwoord:`Leg vast:
- de wens van de klant;
- de berekening van de renteopbouw;
- de gevolgen voor erfgenamen;
- de alternatieven.
Leg ook vast dat de klant het product begrijpt.`,tags:['verzilveren','vastlegging','dossier'],bron:''},
 {id:'hpx-239',thema:'hypotheek-producten',vraag:'Wat is een veelgemaakte fout bij verzilveren?',antwoord:`Een veelgemaakte fout is de renteopbouw onvoldoende uitleggen. Ook worden alternatieven soms niet besproken. Een andere fout is de gevolgen voor erfgenamen niet benoemen. Leg alle afwegingen vast.`,tags:['verzilveren','fouten','renteopbouw'],bron:''},
 {id:'hpx-240',thema:'hypotheek-producten',vraag:'Wat zijn alternatieven voor verzilveren?',antwoord:`Alternatieven zijn verhuizen naar een kleinere woning, verkoop en terughuur, of hulp van familie. Ook een gewone hypotheekverhoging kan soms. Elk alternatief heeft eigen gevolgen. Leg de afweging vast.`,tags:['verzilveren','alternatieven','afweging'],bron:''},
 {id:'hpx-241',thema:'hypotheek-producten',vraag:'Hoe werkt verkoop en terughuur?',antwoord:`Bij verkoop en terughuur verkoopt de klant de woning en huurt deze terug. Daarmee komt de overwaarde vrij. De klant wordt huurder. Bespreek de gevolgen voor zekerheid en woonlasten.`,tags:['verkoop en terughuur','overwaarde','huur'],bron:''},
 {id:'hpx-242',thema:'hypotheek-producten',vraag:'Wat is het belang van wilsbekwaamheid bij verzilveren?',antwoord:`De klant moet het product begrijpen en de gevolgen kunnen overzien. Bij twijfel over wilsbekwaamheid is extra voorzichtigheid nodig. Een levenstestament of volmacht kan helpen. Leg de beoordeling vast.`,tags:['wilsbekwaamheid','verzilveren','volmacht'],bron:''},
 {id:'hpx-243',thema:'hypotheek-producten',vraag:'Wat is het verschil tussen een verzilverlening en een opeethypotheek?',antwoord:`Een verzilverlening wordt meestal eenmalig verstrekt voor een bepaald doel. Een opeethypotheek kan een periodieke uitkering geven. Beide hebben vaak renteopbouw. Controleer de voorwaarden van de aanbieder.`,tags:['verzilverlening','opeethypotheek','verschil'],bron:''},
 {id:'hpx-244',thema:'hypotheek-producten',vraag:'Wat gebeurt er bij overlijden van één partner bij verzilveren?',antwoord:`Bij overlijden van één partner kan de lening vaak doorlopen voor de langstlevende. Dit hangt af van de voorwaarden. Controleer de voorwaarden van de aanbieder. Leg de afspraak vast.`,tags:['verzilveren','overlijden','langstlevende'],bron:''},
 {id:'hpx-245',thema:'hypotheek-producten',vraag:'Mag een klant met een verzilverlening zijn woning verhuren?',antwoord:`Verhuur is vaak niet toegestaan zonder toestemming van de aanbieder. De lening is gebaseerd op bewoning door de klant. Controleer de voorwaarden van de aanbieder. Leg de afspraak vast.`,tags:['verzilverlening','verhuur','toestemming'],bron:''},
 {id:'hpx-246',thema:'hypotheek-producten',vraag:'Wat is het verband tussen verzilveren en onderhoud van de woning?',antwoord:`De woning is de zekerheid voor de lening. De aanbieder kan eisen dat de woning goed wordt onderhouden. Achterstallig onderhoud kan de waarde verlagen. Bespreek dit met de klant.`,tags:['verzilveren','onderhoud','zekerheid'],bron:''},
 {id:'hpx-247',thema:'hypotheek-producten',vraag:'Kan verzilveren worden gebruikt om te schenken aan kinderen?',antwoord:`Dat kan, maar de lening is dan in de regel geen eigenwoningschuld. De renteopbouw verlaagt de nalatenschap. Bespreek de gevolgen voor schenk- en erfbelasting. Laat bij twijfel een fiscalist meekijken.`,tags:['verzilveren','schenken','kinderen'],bron:''},
 {id:'hpx-248',thema:'hypotheek-producten',vraag:'Hoe beoordeelt een aanbieder een lening met renteopbouw zonder maandlast?',antwoord:`Omdat er geen maandlast is, kijkt de aanbieder vooral naar de verhouding tussen de verwachte schuld en de woningwaarde. Daarbij rekent de aanbieder met de groei van de schuld tot een hoge leeftijd. Leeftijd en woningwaarde bepalen daardoor de ruimte. Controleer de voorwaarden van de aanbieder.`,tags:['renteopbouw','acceptatie','woningwaarde'],bron:''},
 {id:'hpx-249',thema:'hypotheek-producten',vraag:'Welke scenarios laat je zien bij een lening met renteopbouw?',antwoord:`Toon de groei van de schuld over bijvoorbeeld 10, 15 en 20 jaar. Zet die af tegen een stijgende, gelijkblijvende en dalende woningwaarde. Zo ziet de klant wat er van de overwaarde overblijft. Leg de scenarios en de reactie van de klant vast.`,tags:['renteopbouw','scenarios','overwaarde'],bron:''},
 {id:'hpx-250',thema:'hypotheek-producten',vraag:'Waarom is een tweede gesprek zinvol bij een verzilveradvies?',antwoord:`Verzilveren heeft grote en langdurige gevolgen. Een tweede gesprek geeft de klant tijd om na te denken en vragen te stellen. Ook kunnen naasten dan aanschuiven als de klant dat wil. Leg vast hoeveel bedenktijd de klant heeft genomen.`,tags:['verzilveren','bedenktijd','zorgvuldigheid'],bron:''}
]);
